    function toggleCurriculumDrawer(forceState) {
      const dr = document.getElementById('curriculum-drawer');
      if (!dr) return;
      if (typeof forceState === 'boolean') dr.classList.toggle('hidden', !forceState);
      else dr.classList.toggle('hidden');
    }
    function navigateRelativeModule(delta) {
      if (!Array.isArray(CURRICULUM_MODULES) || !CURRICULUM_MODULES.length) return;
      const idx = CURRICULUM_MODULES.findIndex(m => m.id === appState.activeModuleId);
      const nextIdx = Math.max(0, Math.min(CURRICULUM_MODULES.length - 1, (idx === -1 ? 0 : idx) + delta));
      selectCurriculumModule(CURRICULUM_MODULES[nextIdx].id, true);
    }

    function renderCurriculumSidebar() {
      const q = (document.getElementById('module-search-input')?.value || '').toLowerCase();
      const lvl = document.getElementById('module-level-filter')?.value || 'ALL';
      const listEl = document.getElementById('curriculum-sidebar-list');
      if (!listEl) return;

      const filtered = CURRICULUM_MODULES.filter(m => {
        if (lvl !== 'ALL' && !(m.level || '').startsWith(lvl)) return false;
        if (!q) return true;
        return (m.title + ' ' + m.subtitle + ' ' + m.chapter + ' ' + m.intuition + ' ' + m.keyPoints.join(' ')).toLowerCase().includes(q);
      });

      const mobSel = document.getElementById('mobile-module-select');
      if (mobSel) {
        mobSel.innerHTML = CURRICULUM_MODULES.map(m => `
          <option value="${m.id}" ${m.id === appState.activeModuleId ? 'selected' : ''}>
            ${m.chapter}: ${m.title}
          </option>
        `).join('');
      }

      listEl.innerHTML = filtered.map(m => {
        const isActive = m.id === appState.activeModuleId;
        const isDone = appState.completedModules.has(m.id);
        return `
          <button onclick="selectCurriculumModule('${m.id}')" class="w-full text-left p-3 rounded-lg border transition-all ${isActive ? 'bg-[var(--primary)] text-[var(--primary-foreground)] border-[var(--primary)] shadow-sm' : 'bg-[var(--content)] text-[var(--foreground)] border-[var(--border)] hover:border-[var(--primary)]'}">
            <div class="flex items-center justify-between text-xs opacity-85">
              <span class="font-bold">${m.chapter}</span>
              <span>${isDone ? '✅ Completed' : m.level}</span>
            </div>
            <div class="font-bold text-xs sm:text-sm mt-1 leading-snug">${m.title}</div>
          </button>
        `;
      }).join('');
    }

    function selectCurriculumModule(modId, scrollToModule = false) {
      const _v7Alias = { 'mod1': 'mod_vec', 'mod2': 'mod4_grad', 'mod3': 'mod_bestfit', 'mod6': 'mod6_odds' };
      modId = _v7Alias[modId] || modId;
      if (typeof toggleCurriculumDrawer === 'function') toggleCurriculumDrawer(false);
      appState.activeModuleId = modId;
      const lvlSel = document.getElementById('module-level-filter');
      const searchIn = document.getElementById('module-search-input');
      const targetMod = CURRICULUM_MODULES.find(m => m.id === modId);
      if (lvlSel && targetMod && lvlSel.value !== 'ALL' && lvlSel.value !== targetMod.level) {
        lvlSel.value = 'ALL';
      }
      if (searchIn && searchIn.value.trim() !== '') {
        searchIn.value = '';
      }
      const mobSel = document.getElementById('mobile-module-select');
      if (mobSel) mobSel.value = modId;
      renderCurriculumSidebar();
      renderActiveCurriculumModule();
      initMatplotlibStudio();
      const contentEl = document.getElementById('curriculum-module-content');
      if (contentEl && scrollToModule) {
        contentEl.scrollIntoView({ behavior: 'auto', block: 'start' });
      }
    }

    function toggleCompleteModule(modId) {
      if (appState.completedModules.has(modId)) {
        appState.completedModules.delete(modId);
      } else {
        appState.completedModules.add(modId);
        addXP(25);
      }
      updateHeaderStats();
      renderCurriculumSidebar();
      renderActiveCurriculumModule();
    }

