    function drawMod0HousingCanvas() {
      const canvas = document.getElementById('mod0-housing-canvas');
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      const W = canvas.width, H = canvas.height;
      ctx.clearRect(0, 0, W, H);
      ctx.fillStyle = '#070b14';
      ctx.fillRect(0, 0, W, H);

      const m = parseFloat(document.getElementById('mod0-slope-slider')?.value || '10');
      const b = parseFloat(document.getElementById('mod0-intercept-slider')?.value || '40');
      const mEl = document.getElementById('mod0-slope-val');
      const bEl = document.getElementById('mod0-intercept-val');
      if (mEl) mEl.textContent = m.toFixed(1) + ' pts/hr';
      if (bEl) bEl.textContent = b.toFixed(0) + ' pts';

      const students = [
        { name: 'S1', x: 1, y: 50 },
        { name: 'S2', x: 2, y: 62 },
        { name: 'S3', x: 3, y: 68 },
        { name: 'S5', x: 5, y: 90 }
      ];
      const pad = { l: 55, r: 25, t: 32, b: 38 };
      const pw = W - pad.l - pad.r, ph = H - pad.t - pad.b;
      const toX = hr => pad.l + (hr / 6.0) * pw;
      const toY = sc => H - pad.b - ((sc - 20) / 85.0) * ph;

      ctx.strokeStyle = '#1e293b'; ctx.lineWidth = 1;
      for (let sc = 30; sc <= 100; sc += 15) {
        ctx.beginPath(); ctx.moveTo(pad.l, toY(sc)); ctx.lineTo(W - pad.r, toY(sc)); ctx.stroke();
        ctx.fillStyle = '#64748b'; ctx.font = '10px monospace'; ctx.textAlign = 'right';
        ctx.fillText(sc + '', pad.l - 6, toY(sc) + 3);
      }
      for (let hr = 0; hr <= 6; hr += 1) {
        ctx.beginPath(); ctx.moveTo(toX(hr), pad.top); ctx.lineTo(toX(hr), H - pad.bottom); ctx.stroke();
        ctx.fillStyle = '#64748b'; ctx.font = '10px monospace'; ctx.textAlign = 'center';
        ctx.fillText(hr + 'h', toX(hr), H - pad.bottom + 14);
      }

      ctx.fillStyle = '#f8fafc'; ctx.font = 'bold 11px system-ui, sans-serif'; ctx.textAlign = 'center';
      ctx.fillText('Starter Student Class: Study Hours (x) vs Quiz Score (y)', pad.l + pw / 2, 18);

      // Line of prediction
      ctx.strokeStyle = '#38bdf8'; ctx.lineWidth = 3;
      ctx.beginPath(); ctx.moveTo(toX(0), toY(m * 0 + b)); ctx.lineTo(toX(6), toY(m * 6 + b)); ctx.stroke();

      let ssr = 0;
      students.forEach(s => {
        const yHat = m * s.x + b;
        const err = yHat - s.y;
        ssr += err * err;
        ctx.strokeStyle = '#ef4444aa'; ctx.lineWidth = 1.5; ctx.setLineDash([3, 3]);
        ctx.beginPath(); ctx.moveTo(toX(s.x), toY(s.y)); ctx.lineTo(toX(s.x), toY(yHat)); ctx.stroke();
        ctx.setLineDash([]);

        ctx.beginPath(); ctx.arc(toX(s.x), toY(s.y), 6, 0, Math.PI * 2);
        ctx.fillStyle = '#10b981'; ctx.fill();
        ctx.strokeStyle = '#ffffff'; ctx.lineWidth = 1.5; ctx.stroke();
        ctx.fillStyle = '#cbd5e1'; ctx.font = 'bold 10px monospace'; ctx.textAlign = 'center';
        ctx.fillText(s.name + ' (' + s.y + ')', toX(s.x), toY(s.y) - 10);
      });

      // Predicted Student 4 at 4 hours
      const s4Pred = m * 4 + b;
      ctx.beginPath(); ctx.arc(toX(4), toY(s4Pred), 6, 0, Math.PI * 2);
      ctx.fillStyle = '#fbbf24'; ctx.fill();
      ctx.strokeStyle = '#ffffff'; ctx.lineWidth = 2; ctx.stroke();
      ctx.fillStyle = '#fbbf24'; ctx.font = 'bold 10px monospace';
      ctx.fillText('Predict S4: ' + s4Pred.toFixed(0), toX(4), toY(s4Pred) - 11);

      const mse = ssr / students.length;
      const rmse = Math.sqrt(mse);
      const rEl = document.getElementById('mod0-housing-readout');
      if (rEl) {
        const isOptimal = ssr <= 10;
        rEl.innerHTML = `
          <div class="font-bold text-emerald-400 uppercase tracking-wider text-[11px]">📊 Live Rule Scoreboard (No Algebra Jargon!)</div>
          <div class="p-2.5 rounded-lg bg-slate-950 border border-slate-800 font-mono text-xs">
            Rule: <strong>Score = ${m.toFixed(1)} × Hours + ${b.toFixed(0)}</strong>
          </div>
          <div class="grid grid-cols-2 gap-2 font-mono">
            <div class="p-2 rounded bg-slate-900 border border-slate-800">
              <div class="text-[10px] text-slate-400">Total Mistake² (Model Squared Error)</div>
              <div class="text-sm font-black ${isOptimal ? 'text-emerald-400' : 'text-amber-400'}">${ssr.toFixed(1)}</div>
            </div>
            <div class="p-2 rounded bg-slate-900 border border-slate-800">
              <div class="text-[10px] text-slate-400">Typical Miss</div>
              <div class="text-sm font-black text-sky-400">±${rmse.toFixed(2)} pts</div>
            </div>
          </div>
          <div class="p-2.5 rounded-lg ${isOptimal ? 'bg-emerald-950/50 border-emerald-500/40 text-emerald-300' : 'bg-amber-950/40 border-amber-500/40 text-amber-300'} border">
            ${isOptimal ? '🎉 Best Fit Reached! Student 4 (4 hrs) is predicted to score ' + s4Pred.toFixed(1) + ' pts with Typical Error ±1.41!' : '💡 Try moving sliders closer to m = 10.0 and b = 40 to shrink those dashed red mistake bars down to Model Squared Error = 8.0!'}
          </div>
        `;
      }
    }
