      if (elBeds) elBeds.textContent = `${beds} bedrooms`;
      const elAge = document.getElementById('step2-age-val');
      if (elAge) elAge.textContent = `${age} years old`;

      const w1 = 150;
      const w2 = 20000;
      const w3 = -2000;
      const b = 50000;

      const term1 = w1 * sqft;
      const term2 = w2 * beds;
      const term3 = w3 * age;
      const guessY = term1 + term2 + term3 + b;

      const trueY = 410000;
