      const naiveY = 320000;
      const naiveMistake = naiveY - trueY;

      const elT1 = document.getElementById('step2-term1-val');
      if (elT1) elT1.textContent = `+$${term1.toLocaleString()}`;
      const elT2 = document.getElementById('step2-term2-val');
