    let mod0CurrentShot = 1;
    function shootMod0Robot(shotNum) {
      mod0CurrentShot = shotNum;
      drawMod0RobotCanvas();
    }

    function drawMod0RobotCanvas() {
      const canvas = document.getElementById('mod0-robot-canvas');
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      const W = canvas.width;
      const H = canvas.height;
      ctx.clearRect(0, 0, W, H);

      ctx.fillStyle = '#0f172a';
      ctx.fillRect(0, 0, W, H);

      ctx.strokeStyle = '#334155';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(20, H - 25);
      ctx.lineTo(W - 20, H - 25);
      ctx.stroke();

      const hoopX = W - 80;
      const hoopY = 70;

      ctx.fillStyle = '#f8fafc';
      ctx.fillRect(hoopX + 18, 30, 4, 60);

      ctx.strokeStyle = '#f97316';
      ctx.lineWidth = 3;
      ctx.beginPath();
      ctx.moveTo(hoopX - 10, hoopY);
      ctx.lineTo(hoopX + 18, hoopY);
      ctx.stroke();

      ctx.strokeStyle = 'rgba(255, 255, 255, 0.4)';
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(hoopX - 10, hoopY);
      ctx.lineTo(hoopX - 4, hoopY + 22);
      ctx.lineTo(hoopX + 12, hoopY + 22);
      ctx.lineTo(hoopX + 18, hoopY);
      ctx.stroke();

      const robX = 60;
      const robY = H - 25;

      ctx.fillStyle = '#38bdf8';
      ctx.fillRect(robX - 14, robY - 45, 28, 45);
      ctx.fillStyle = '#7dd3fc';
      ctx.fillRect(robX - 10, robY - 65, 20, 18);
      ctx.fillStyle = '#0f172a';
      ctx.fillRect(robX, robY - 58, 6, 4);

      const shots = [
        { num: 1, endX: hoopX + 55, endY: hoopY + 30, ctrlX: (robX + hoopX)/2, ctrlY: 10, err: "Missed long by 2.0m (Error = 4.0)", col: "#f43f5e" },
        { num: 2, endX: hoopX + 18, endY: hoopY - 5, ctrlX: (robX + hoopX)/2, ctrlY: 25, err: "Missed off rim by 0.4m (Error = 0.16)", col: "#f59e0b" },
        { num: 3, endX: hoopX + 4, endY: hoopY + 10, ctrlX: (robX + hoopX)/2, ctrlY: 35, err: "SWISH! Error = 0.00! Nothing but net!", col: "#10b981" }
      ];

      const s = shots[mod0CurrentShot - 1];

      ctx.setLineDash([5, 4]);
      ctx.strokeStyle = s.col;
      ctx.lineWidth = 2.5;
      ctx.beginPath();
      ctx.moveTo(robX + 10, robY - 50);
      ctx.quadraticCurveTo(s.ctrlX, s.ctrlY, s.endX, s.endY);
      ctx.stroke();
      ctx.setLineDash([]);

      ctx.fillStyle = '#f97316';
      ctx.beginPath();
      ctx.arc(s.endX, s.endY, 7, 0, Math.PI * 2);
      ctx.fill();
      ctx.strokeStyle = '#ffffff';
      ctx.lineWidth = 1.5;
      ctx.stroke();

      ctx.fillStyle = s.col;
      ctx.font = 'bold 12px Inter, sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(`Shot #${s.num}: ${s.err}`, W / 2, 22);

      const robExpl = document.getElementById('step2-robot-expl');
      if (robExpl) {
        robExpl.innerHTML = `
          <div class="flex items-center justify-between border-b border-[var(--border)] pb-2 mb-2">
            <span class="font-bold text-xs text-[var(--foreground)]">Optimization Step ${s.num} of 3:</span>
            <div class="flex gap-1.5">
              <button onclick="shootMod0Robot(1)" class="px-2 py-0.5 rounded text-[11px] font-bold ${mod0CurrentShot === 1 ? 'bg-rose-600 text-white' : 'bg-[var(--card)] border border-[var(--border)]'}">Shot 1 (Miss)</button>
              <button onclick="shootMod0Robot(2)" class="px-2 py-0.5 rounded text-[11px] font-bold ${mod0CurrentShot === 2 ? 'bg-amber-600 text-white' : 'bg-[var(--card)] border border-[var(--border)]'}">Shot 2 (Nudge)</button>
              <button onclick="shootMod0Robot(3)" class="px-2 py-0.5 rounded text-[11px] font-bold ${mod0CurrentShot === 3 ? 'bg-emerald-600 text-white' : 'bg-[var(--card)] border border-[var(--border)]'}">Shot 3 (Swish!)</button>
            </div>
          </div>
          <p class="text-xs text-[var(--muted-foreground)] leading-relaxed">
            ${mod0CurrentShot === 1
              ? `• <strong>Shot 1:</strong> Robot starts with arbitrary random arm knob (w₁ = 85° angle, w₂ = 12 m/s force). The ball sails 2 meters past the rim. The loss function computes Squared Error = (2.0)² = 4.0.`
              : mod0CurrentShot === 2
                ? `• <strong>Shot 2:</strong> Gradient descent evaluates the slope ∂J/∂w. Because the shot was too long, the gradient tells the robot to subtract force: Updated Weight = w_old − η(∂J/∂w). The ball hits the back rim—much closer!`
                : `• <strong>Shot 3:</strong> After another gentle gradient downhill step, the dials converge on the global minimum! The ball drops cleanly through the center of the hoop. Training complete!`}
          </p>
        `;
      }
    }

    // 4. UNIVERSAL FORMATTER FOR ALL CURRICULUM MODULES (Zero Ugly Monospace Walls!)
    // =========================================================================
    // UNIVERSAL EYE-FRIENDLY WORKED EXAMPLE PARSER & MULTI-CARD STUDIOS
