    score_R = (G_R ** 2) / (H_R + reg_lambda)
    score_P = ((G_L + G_R) ** 2) / (H_L + H_R + reg_lambda)
    gain = 0.5 * (score_L + score_R - score_P) - gamma
    return w_L, w_R, gain

