    function renderCodingSidebar() {
      const listEl = document.getElementById('coding-labs-list');
      if (!listEl) return;
      listEl.innerHTML = CODING_LABS.map(lab => {
        const isActive = lab.id === appState.activeLabId;
        const isDone = appState.completedLabs.has(lab.id);
        return `
          <button onclick="selectCodingLab(${lab.id})" class="w-full text-left p-2.5 rounded-lg border transition-all ${isActive ? 'bg-[var(--primary)] text-[var(--primary-foreground)] border-[var(--primary)] shadow-sm' : 'bg-[var(--content)] text-[var(--foreground)] border-[var(--border)] hover:border-[var(--primary)]'}">
            <div class="flex items-center justify-between text-xs opacity-85">
              <span class="font-bold">${lab.badge}</span>
              <span>${isDone ? '✅' : '○'}</span>
            </div>
            <div class="text-xs sm:text-sm font-semibold mt-0.5 line-clamp-1">${lab.title}</div>
          </button>
        `;
      }).join('');
    }

    function selectCodingLab(labId) {
      appState.activeLabId = labId;
      const mobSel = document.getElementById('mobile-coding-select');
      if (mobSel) mobSel.value = labId;
      renderCodingSidebar();
      const lab = CODING_LABS.find(l => l.id === labId) || CODING_LABS[0];
      document.getElementById('coding-lab-badge').textContent = lab.badge;
      document.getElementById('coding-lab-title').textContent = lab.title;
      document.getElementById('coding-lab-desc').innerHTML = lab.desc;
      document.getElementById('coding-editor-textarea').value = lab.starter;
      document.getElementById('coding-hint-box').classList.add('hidden');
      document.getElementById('coding-console-output').textContent = 'Click "▶ Run & Verify Code" to execute and inspect output...';
      document.getElementById('coding-matplotlib-img-wrap').classList.add('hidden');
      document.getElementById('coding-test-results').innerHTML = '<p class="text-[var(--muted-foreground)]">Unit assertions will run automatically when you execute your code.</p>';
    }

    function showCodingHint() {
      const lab = CODING_LABS.find(l => l.id === appState.activeLabId);
      const box = document.getElementById('coding-hint-box');
      if (lab && box) {
        box.innerHTML = `<strong>💡 Mathematical &amp; API Hint:</strong> ${lab.hint}`;
        box.classList.toggle('hidden');
      }
    }

    function revealCodingSolution() {
      const lab = CODING_LABS.find(l => l.id === appState.activeLabId);
      if (lab) {
        document.getElementById('coding-editor-textarea').value = lab.solution;
      }
    }

    function resetCodingEditor() {
      const lab = CODING_LABS.find(l => l.id === appState.activeLabId);
      if (lab) {
        document.getElementById('coding-editor-textarea').value = lab.starter;
      }
    }

    async function runCodingChallenge() {
      const lab = CODING_LABS.find(l => l.id === appState.activeLabId);
      if (!lab) return;
      const code = document.getElementById('coding-editor-textarea').value;
      const consoleEl = document.getElementById('coding-console-output');
      const testEl = document.getElementById('coding-test-results');
      const imgWrap = document.getElementById('coding-matplotlib-img-wrap');
      imgWrap.classList.add('hidden');

      // 1. Run Structural & Mathematical Unit Assertions
      let allPassed = true;
      const testHtml = lab.checks.map(chk => {
        const passed = chk.test(code);
        if (!passed) allPassed = false;
        return `
          <div class="p-2 rounded border ${passed ? 'border-emerald-500/40 bg-emerald-500/10 text-emerald-300' : 'border-rose-500/40 bg-rose-500/10 text-rose-300'} flex items-center justify-between">
            <span>${passed ? '✅ PASS' : '❌ FAIL'}: ${chk.name}</span>
          </div>
        `;
      }).join('');
      testEl.innerHTML = testHtml;

      // 2. Try Optional Local Python 3.14 Backend Server (http://localhost:8765/run) first; fallback to Built-in Numerical Verifier
      try {
        const controller = new AbortController();
        const timer = setTimeout(() => controller.abort(), 1800);
        const resp = await fetch('http://localhost:8765/run', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ code }),
          signal: controller.signal
        });
        clearTimeout(timer);
        if (resp.ok) {
          const data = await resp.json();
          document.getElementById('coding-exec-mode-label').textContent = '🟢 Connected: Live Python 3.14 Kernel (localhost:8765)';
          consoleEl.textContent = data.stdout || data.stderr || '(No stdout)';
          if (data.image_base64) {
            document.getElementById('coding-matplotlib-img').src = 'data:image/png;base64,' + data.image_base64;
            imgWrap.classList.remove('hidden');
          }
          if (allPassed && !data.stderr && !appState.completedLabs.has(lab.id)) {
            appState.completedLabs.add(lab.id);
            addXP(150);
            renderCodingSidebar();
          }
          return;
        }
      } catch (_) {
        // Offline / Sandbox Mode: Use Built-in Verified Output Engine
      }

      if (allPassed) {
        consoleEl.textContent = lab.expectedOut + '\n\n[✔ Verified all mathematical invariants & matrix dimensions]';
        if (!appState.completedLabs.has(lab.id)) {
          appState.completedLabs.add(lab.id);
          addXP(150);
          renderCodingSidebar();
        }
      } else {
        consoleEl.textContent = '⚠️ One or more mathematical unit assertions failed. Check the right panel or click "👁️ Load Solution".';
      }
    }

    // =========================================================================
    // 6. INTERACTIVE MASTERY QUIZ BANK (48 QUESTIONS WITH MATH EXPLANATIONS)
    // =========================================================================
    const QUIZ_BANK = [
      // CAT0: Formula Anatomy, Linear Algebra, Calculus & Info Theory (8 Qs)
      { id: 'q1', cat: 'CAT0', q: 'In the equation Average Squared Error = (1/m) ∑_{i=1}^m (ŷ^(i) - y^(i))², what does the sub-expression (1/m) ∑_{i=1}^m (...) ALWAYS mean in Machine Learning?', opts: ['Multiply the first row by m', 'Take the arithmetic average (mean) across all m rows in the dataset', 'Take the derivative with respect to m', 'Raise the prediction to the m-th power'], ans: 1, exp: 'Adding up m items with ∑_{i=1}^m and dividing by m is the definition of the sample mean (`np.mean(...)`).' },
      { id: 'q2', cat: 'CAT0', q: 'What is the difference between θ* = min_θ J(θ) and θ* = arg min_θ J(θ)?', opts: ['They are identical', 'min_θ returns the lowest loss score, whereas arg min_θ returns the optimal parameter settings θ* that achieved that lowest loss', 'arg min_θ maximizes the loss', 'arg min_θ only works on discrete integers'], ans: 1, exp: '<code>min</code> returns the minimum output value of J; `arg min` ("argument of the minimum") returns the input knob values θ* where that minimum occurs.' },
      { id: 'q3', cat: 'CAT0', q: 'Given vector w = [3, -4]ᵀ, what are its Manhattan Norm (‖w‖₁), Euclidean Norm (‖w‖₂), and Max Norm (‖w‖_∞)?', opts: ['‖w‖₁ = 5, ‖w‖₂ = 7, ‖w‖_∞ = 4', '‖w‖₁ = 7, ‖w‖₂ = 5, ‖w‖_∞ = 4', '‖w‖₁ = -1, ‖w‖₂ = 25, ‖w‖_∞ = 3', '‖w‖₁ = 7, ‖w‖₂ = 25, ‖w‖_∞ = -4'], ans: 1, exp: '‖w‖₁ = |3| + |-4| = 7; ‖w‖₂ = √(3² + (-4)²) = √25 = 5; ‖w‖_∞ = max(|3|, |-4|) = 4.' },
      { id: 'q4', cat: 'CAT0', q: 'If two non-zero feature vectors a and b are perpendicular (orthogonal, θ = 90°), what is their dot product aᵀb?', opts: ['+1', '-1', '0', '‖a‖₂ · ‖b‖₂'], ans: 2, exp: 'Since aᵀb = ‖a‖₂ ‖b‖₂ cos(90°) and cos(90°) = 0, orthogonal vectors always have a dot product of 0.' },
      { id: 'q5', cat: 'CAT0', q: 'Using the Chain Rule on ŷ = w·x + b and 𝓛 = (ŷ - y)², what is ∂𝓛/∂w when x = 4, y = 10, w = 2, b = 0?', opts: ['-4', '-16', '+16', '+8'], ans: 1, exp: 'ŷ = 2(4)+0 = 8. Outer derivative ∂𝓛/∂ŷ = 2(8 - 10) = -4. Inner derivative ∂ŷ/∂w = x = 4. Product = (-4)(4) = -16.' },
      { id: 'q6', cat: 'CAT0', q: 'Under a Bayesian lens, minimizing Average Squared Error is mathematically equivalent to Maximum Likelihood Estimation (MLE) under what noise assumption?', opts: ['Laplace noise', 'Zero-mean Gaussian (Normal) noise ε ~ 𝓝(0, σ²)', 'Poisson noise', 'Uniform noise'], ans: 1, exp: 'Taking the negative log-likelihood of Gaussian noise p(y|x) ∝ exp(-(y - ŷ)²/(2σ²)) yields ½∑(y - ŷ)².' },
      { id: 'q7', cat: 'CAT0', q: 'In Information Theory, how are Cross-Entropy H(P, Q), Character Randomness H(P), and KL Divergence D_KL(P ‖ Q) related?', opts: ['H(P, Q) = H(P) + D_KL(P ‖ Q)', 'H(P, Q) = H(P) · D_KL(P ‖ Q)', 'D_KL(P ‖ Q) = 0 always', 'H(P) = H(P, Q) + D_KL(P ‖ Q)'], ans: 0, exp: 'Since H(P) is fixed for the ground-truth labels P, minimizing Cross-Entropy Loss H(P, Q) is identical to minimizing KL Divergence D_KL(P ‖ Q)!' },
      { id: 'q8', cat: 'CAT0', q: 'Why must you NEVER call `scaler.fit_transform(X_test)` on your test set?', opts: ['It raises a SyntaxError in Python', 'It recomputes test-set mean and std, leaking test distribution information and distorting the coordinate frame expected by the trained model', 'It deletes the target column', 'It converts float64 to int32'], ans: 1, exp: 'Always call `fit_transform(X_train)` and `transform(X_test)` so test samples are measured using the exact training mean and standard deviation.' },

      // CAT1: Linear/Ridge/Lasso, Gradient Descent, Logistic, KNN & Naive Bayes (8 Qs)
      { id: 'q9', cat: 'CAT1', q: 'What is the time complexity of inverting the (n × n) matrix XᵀX in the Direct Best-Fit Formula ŵ = (XᵀX)⁻¹Xᵀy?', opts: ['O(n)', 'O(n log n)', 'O(n³)', 'O(1)'], ans: 2, exp: 'Matrix inversion scales cubically O(n³) in the number of features n, making it impractical when n > 10,000.' },
      { id: 'q10', cat: 'CAT1', q: 'How does <code>sklearn.linear_model.LinearRegression</code> avoid crashing when two features in X are perfectly collinear (so XᵀX is singular)?', opts: ['It drops half the rows randomly', 'It computes the Moore-Penrose pseudoinverse X⁺y via Singular Value Decomposition (SVD)', 'It switches to Decision Trees', 'It adds L1 Lasso penalty automatically'], ans: 1, exp: '<code>LinearRegression</code> uses <code>scipy.linalg.lstsq</code> (SVD X = USVᵀ), zeroing out inverted singular values below machine precision instead of dividing by zero.' },
      { id: 'q11', cat: 'CAT1', q: 'Why does Adam divide m_t by (1 - β₁ᵗ) and v_t by (1 - β₂ᵗ) during the first few training steps?', opts: ['To increase regularization', 'Because m_0 = 0 and v_0 = 0 initialize the moving averages near zero, biasing early estimates downward when β₁=0.9, β₂=0.999', 'To compute the matrix determinant', 'To convert L2 norm to L1 norm'], ans: 1, exp: 'At t=1 with β₂=0.999, v₁ = 0.001 g₁² is 1000× too small without dividing by (1 - 0.999¹) = 0.001.' },
      { id: 'q12', cat: 'CAT1', q: 'Why does Lasso (L₁) Regularization drive irrelevant weights to EXACT 0.0 while Ridge (L₂) only shrinks them toward zero?', opts: ['Lasso has a constant subgradient ±λ all the way to 0 (diamond corners on axes), acting as a Soft-Thresholding operator S_λ(z)', 'Lasso uses a larger learning rate', 'Ridge only penalizes the intercept b', 'Lasso squares the weights'], ans: 0, exp: 'Ridge derivative 2λw_j vanishes as w_j → 0, whereas Lasso derivative λ·sign(w_j) pushes with constant force ±λ right into 0.0.' },
      { id: 'q13', cat: 'CAT1', q: 'In Logistic Regression, if the linear logit score z = wᵀx + b equals 0, what is the predicted probability p̂ = σ(z)?', opts: ['0.00', '0.50', '1.00', '0.731'], ans: 1, exp: 'σ(0) = 1 / (1 + e⁰) = 1 / (1 + 1) = 0.50. Thus wᵀx + b = 0 is the 50% decision boundary hyperplane!' },
      { id: 'q14', cat: 'CAT1', q: 'In Scikit-Learn\'s `LogisticRegression(C=0.01)` and `SVC(C=0.01)`, what does a very SMALL value of <code>C</code> do?', opts: ['Applies very STRONG regularization (simpler model, wider street, smaller weights)', 'Applies very WEAK regularization (complex model, narrower street)', 'Sets learning rate to 0.01', 'Uses 1% of the data'], ans: 0, exp: '`C = 1 / λ` is inverse regularization strength: small C means huge λ penalty on weights.' },
      { id: 'q15', cat: 'CAT1', q: 'In a 100-dimensional unit hypercube [0, 1]^100, what edge length ℓ is needed to capture 10% of uniformly distributed data?', opts: ['10.0% of each axis', '31.6% of each axis', '97.7% of each axis (0.10^(1/100) ≈ 0.977)', '50.0% of each axis'], ans: 2, exp: 'Because ℓ^100 = 0.10 ⇒ ℓ = 0.10^(0.01) = 0.977, there are no "local" neighborhoods in high dimensions—the Curse of Dimensionality!' },
      { id: 'q16', cat: 'CAT1', q: 'Why does Multinomial Naive Bayes add Zero-Proof Safety Padding (+α in numerator, +α|V| in denominator) and sum log-probabilities?', opts: ['To speed up matrix inversion', 'Laplace prevents unseen test words (count=0) from zeroing out the entire product, and logs prevent float64 underflow', 'To normalize features to [-1, 1]', 'To prune decision trees'], ans: 1, exp: 'Without α > 0, a single new word gives P(w|c)=0 and wipes out all other evidence; summing ln P converts tiny products into stable additions.' },

      // CAT2: SVMs, Kernels, Decision Trees, Random Forests, XGBoost & Metrics (8 Qs)
      { id: 'q17', cat: 'CAT2', q: 'What is the exact geometric width of the margin street between wᵀx + b = +1 and wᵀx + b = -1 in a Support Vector Machine?', opts: ['‖w‖₂', '2 / ‖w‖₂', '1 / C', 'wᵀx + b'], ans: 1, exp: 'Projecting the displacement vector (x₊ - x₋) onto the unit normal w/‖w‖₂ gives (wᵀ(x₊ - x₋))/‖w‖₂ = 2 / ‖w‖₂.' },
      { id: 'q18', cat: 'CAT2', q: 'What happens to the decision boundary of an RBF Kernel SVM `SVC(kernel="rbf", gamma=100.0)` when γ (gamma) is made huge?', opts: ['The boundary becomes a flat straight line', 'Each training point\'s Gaussian bell becomes spiky and narrow, wrapping tight overfitting islands around individual points', 'All points are classified as Class 0', 'Margin width becomes infinite'], ans: 1, exp: 'In K(x,z) = exp(-γ‖x-z‖²), huge γ makes the exponential decay rapidly with distance, creating isolated micro-islands around training points.' },
      { id: 'q19', cat: 'CAT2', q: 'A Decision Tree parent node has 6 Positives and 4 Negatives (Gini = 0.480). A split produces Left (6⊕, 0⊖) and Right (0⊕, 4⊖). What is the Gini Information Gain?', opts: ['0.000', '0.240', '+0.480 (maximum possible reduction to 0 impurity)', '1.000'], ans: 2, exp: 'Both children are 100% pure (Gini_L = 0, Gini_R = 0), so Gain = 0.480 - (0.6×0 + 0.4×0) = +0.480.' },
      { id: 'q20', cat: 'CAT2', q: 'Why do Decision Trees, Random Forests, and XGBoost NOT require <code>StandardScaler</code> on numeric features?', opts: ['They normalize features internally via SVD', 'Monotonic scaling (multiplying a column by 1000) shifts split thresholds by 1000× but never changes which samples fall left vs. right!', 'They only accept binary 0/1 features', 'They use Cosine distance'], ans: 1, exp: 'Tree splits only depend on the sorted rank order of a feature: x_j ≤ t has the exact same subset partition as 1000·x_j ≤ 1000·t.' },
      { id: 'q21', cat: 'CAT2', q: 'If B trees have pairwise correlation ρ and variance σ², the ensemble variance is ρσ² + ((1-ρ)/B)σ². How does a Random Forest reduce the first term ρσ²?', opts: ['By increasing B to infinity', 'By selecting a random subset of <code>max_features</code> (e.g. √n) at each split so one dominant feature cannot make all trees identical', 'By pruning trees to depth 1', 'By setting bootstrap=False'], ans: 1, exp: 'Increasing B only shrinks ((1-ρ)/B)σ². Feature subsampling (`max_features="sqrt"`) decorrelates the trees, shrinking ρ itself!' },
      { id: 'q22', cat: 'CAT2', q: 'In XGBoost, given summed first derivatives G_j = ∑ g_i and summed Hessians H_j = ∑ h_i in leaf j with L₂ penalty λ, what is the optimal leaf weight w_j*?', opts: ['-G_j / H_j', '-G_j / (H_j + λ)', '-H_j / (G_j + λ)', '-λ · G_j'], ans: 1, exp: 'Minimizing the 2nd-order Taylor quadratic G_j w_j + ½(H_j + λ)w_j² with respect to w_j yields w_j* = -G_j / (H_j + λ).' },
      { id: 'q23', cat: 'CAT2', q: 'In a credit card fraud dataset where 99.9% of transactions are legitimate and 0.1% are fraud, why is Accuracy a terrible metric?', opts: ['Accuracy cannot be computed on binary targets', 'A dummy model predicting "0 (Not Fraud)" 100% of the time achieves 99.9% Accuracy while catching 0% of frauds (Recall = 0)!', 'Accuracy is always 0.50', 'Accuracy requires balanced trees'], ans: 1, exp: 'On imbalanced datasets, always use Precision-Recall AUC (PR-AUC), Precision-Recall Balance/F_β Score, or Balanced Overall Score.' },
      { id: 'q24', cat: 'CAT2', q: 'What is the probabilistic physical meaning of a model\'s Ranking Accuracy?', opts: ['The fraction of positive predictions that are correct', 'The probability that the model ranks a randomly chosen Positive instance higher than a randomly chosen Negative instance', 'The Average Squared Error of probabilities', 'The ratio of TP to TN'], ans: 1, exp: 'Ranking Accuracy is equivalent to the Mann-Whitney U / Wilcoxon rank-sum statistic measuring pairwise ranking separation.' },

      // CAT3: Unsupervised Clustering, PCA, Manifolds & Anomaly Detection (8 Qs)
      { id: 'q25', cat: 'CAT3', q: 'Why does `KMeans(init="k-means++")` outperform random centroid initialization?', opts: ['It automatically chooses K', 'It picks subsequent initial centroids with probability proportional to squared distance D(x)² from existing centroids, spreading them apart', 'It uses Manhattan distance', 'It removes outliers before clustering'], ans: 1, exp: 'K-Means++ prevents multiple initial centroids from spawning inside the same dense cluster.' },
      { id: 'q26', cat: 'CAT3', q: 'Which clustering algorithm can discover arbitrary non-convex shapes (like interlocking moons) AND automatically flag isolated outliers as <code>-1</code> (Noise)?', opts: ['K-Means', 'DBSCAN / HDBSCAN', 'Gaussian Mixture Models (GMM)', 'MiniBatchKMeans'], ans: 1, exp: 'DBSCAN groups density-reachable core points (≥ MinPts within radius ε) and labels isolated low-density points as -1.' },
      { id: 'q27', cat: 'CAT3', q: 'How does a Gaussian Mixture Model (GMM) generalize K-Means?', opts: ['It only allows K=2 clusters', 'It fits full covariance matrices Σ_k (elliptical clusters) and computes soft posterior responsibilities γ_ik via the EM algorithm', 'It requires class labels y', 'It uses decision trees'], ans: 1, exp: 'K-Means is a special hard-assignment limit of GMM where every cluster has spherical isotropic covariance Σ_k = εI.' },
      { id: 'q28', cat: 'CAT3', q: 'In Principal Component Analysis (PCA), how is the fraction of total variance explained by the k-th principal component computed?', opts: ['λ_k / ∑_{j=1}^n λ_j (where λ_k is the k-th largest eigenvalue of the covariance matrix Σ)', '‖v_k‖₂', 'det(Σ)', '1 / k'], ans: 0, exp: 'Each eigenvalue λ_k equals the variance of the data projected onto eigenvector v_k, and trace(Σ) = ∑ λ_j is total variance.' },
      { id: 'q29', cat: 'CAT3', q: 'Why did t-SNE replace the Gaussian distribution in the low-dimensional 2D map with a Student-t distribution (df=1, Cauchy)?', opts: ['To make the math linear', 'Its heavier tails alleviate the "Crowding Problem," allowing moderately distant high-dimensional clusters to spread apart cleanly in 2D', 'To compute eigenvalues faster', 'To allow transform(X_test)'], ans: 1, exp: 'Volume scales as r^d in high dimensions vs r² in 2D; Student-t heavy tails (1 + ‖z_i - z_j‖²)⁻¹ give medium-distance points room in 2D.' },
      { id: 'q30', cat: 'CAT3', q: 'What is the foundational geometric intuition behind <code>IsolationForest</code> for anomaly detection?', opts: ['Anomalies sit near cluster centers', 'Random axis-aligned cuts isolate rare extreme outliers in very few splits (short path length E[h(x)] near the root), whereas normal dense points require many splits', 'It fits a 10-layer neural network', 'It computes Mahalanobis distance'], ans: 1, exp: 'In the anomaly score s(x, m) = 2^(-E[h(x)]/c(m)), small average tree depth E[h(x)] → 0 pushes s(x, m) → 1.0 (Anomaly).' },
      { id: 'q31', cat: 'CAT3', q: 'If a Silhouette Score s(i) = (b(i) - a(i)) / max(a(i), b(i)) for a point is negative (near -1), what does that indicate?', opts: ['The point is perfectly clustered', 'The point is closer on average to a neighboring cluster b(i) than to its own assigned cluster a(i) (misassigned!)', 'There is only 1 cluster', 'Features are orthogonal'], ans: 1, exp: 'When intra-cluster distance a(i) > nearest other-cluster distance b(i), b(i) - a(i) < 0.' },
      { id: 'q32', cat: 'CAT3', q: 'When reducing dimensionality of a sparse <code>scipy.sparse.csr_matrix</code> (such as 50,000 Rare-Pattern Score text columns), why should you use <code>TruncatedSVD</code> instead of <code>PCA</code>?', opts: ['PCA only works on 2 columns', 'Mean-centering X - μ in standard PCA destroys sparsity (turning millions of 0s into dense non-zeros and blowing up RAM), whereas TruncatedSVD operates directly on sparse X', 'TruncatedSVD is nonlinear', 'PCA cannot compute explained variance'], ans: 1, exp: 'Subtracting a non-zero column mean from a 99%-zero CSR matrix fills every zero entry, causing an instant <code>MemoryError</code>.' },

      // CAT4: Leak-Free Pipelines, Deep Learning, CNNs, LSTMs, Transformers & RL (8 Qs)
      { id: 'q33', cat: 'CAT4', q: 'In a multi-hospital medical study where each patient has 10 rows of lab visits, which Scikit-Learn splitter prevents the same patient from appearing in both train and validation folds?', opts: ['KFold(shuffle=True)', 'GroupKFold / StratifiedGroupKFold(groups=patient_id)', 'TimeSeriesSplit', 'train_test_split'], ans: 1, exp: 'Without `groups=patient_id`, the model memorizes patient-specific baselines across folds (Entity Leakage).' },
      { id: 'q34', cat: 'CAT4', q: 'Why must all weights in a Multi-Layer Perceptron (MLP) NEVER be initialized to <code>0.0</code> (Zero Initialization)?', opts: ['It causes division by zero in ReLU', 'Every neuron in a hidden layer computes the exact same forward value and receives the exact same gradient (Symmetry Problem), acting like a single neuron forever!', 'It causes exploding gradients', 'PyTorch raises a ValueError'], ans: 1, exp: 'Use He Initialization W ~ 𝓝(0, 2/n_in) for ReLU/GELU or Xavier Initialization W ~ 𝓝(0, 2/(n_in+n_out)) for Tanh/Sigmoid to break symmetry.' },
      { id: 'q35', cat: 'CAT4', q: 'How do Residual Skip Connections `y = x + F(x)` (ResNets & Transformers) prevent the Vanishing Gradient Problem in 100-layer networks?', opts: ['They remove all activation functions', 'By the Chain Rule, ∂y/∂x = I + ∂F(x)/∂x—the identity term +I creates an unimpeded gradient superhighway where upstream gradients flow backward without shrinking to 0!', 'They double the batch size', 'They replace Adam with SGD'], ans: 1, exp: 'Even if ∂F/∂x is near 0 in a given block, multiplying by (1 + ∂F/∂x) preserves the gradient signal all the way to the first layer.' },
      { id: 'q36', cat: 'CAT4', q: 'A 32×32 RGB image is passed through a <code>Conv2d</code> layer with 16 filters, kernel size K=3, padding P=1, and stride S=1. What is the output spatial width W_out?', opts: ['30', '32', '16', '34'], ans: 1, exp: 'W_out = ⌊(32 - 3 + 2(1)) / 1⌋ + 1 = ⌊31 / 1⌋ + 1 = 32 ("Same" padding preserves spatial dimensions!).' },
      { id: 'q37', cat: 'CAT4', q: 'In a Transformer\'s Scaled Dot-Product Attention `softmax((Q Kᵀ) / √Head Size) V`, why do we divide the dot products by `√Head Size`?', opts: ['To reduce memory usage', 'For unit-variance Q and K, the dot product Q·K has variance Head Size; dividing by √Head Size restores variance to 1.0 so Softmax does not saturate into flat 0/1 regions with vanishing gradients', 'To make the matrix symmetric', 'To remove positional encoding'], ans: 1, exp: 'If Head Size = 64, raw dot products have standard deviation √64 = 8, pushing e^z into extreme saturation where Softmax gradients vanish.' },
      { id: 'q38', cat: 'CAT4', q: 'In Reinforcement Learning, why is Q-Learning called an "Off-Policy" Temporal Difference algorithm?', opts: ['It does not use rewards', 'Its Bellman target R + γ max_{a\'} Q(S\', a\') evaluates the greedy optimal action max_{a\'} even while the agent explores using an ε-greedy behavior policy!', 'It only updates at the end of an episode', 'It requires a transition matrix P(s\'|s,a)'], ans: 1, exp: 'SARSA is On-Policy (uses the actual next action A\' taken), whereas Q-Learning bootstraps from the greedy max_{a\'} Q(S\', a\').' },
      { id: 'q39', cat: 'CAT4', q: 'When training a Regressor on right-skewed house prices where <code>y_train</code> was transformed via `np.log1p(y)`, how do you automate both forward <code>log1p</code> and inverse <code>expm1</code> cleanly in Scikit-Learn?', opts: ['StandardScaler', 'TransformedTargetRegressor(regressor=model, func=np.log1p, inverse_func=np.expm1)', 'PolynomialFeatures', 'Binarizer'], ans: 1, exp: '<code>TransformedTargetRegressor</code> automatically transforms <code>y</code> during `.fit()` and applies <code>expm1</code> to predictions during `.predict()`.' },
      { id: 'q40', cat: 'CAT4', q: 'In an LSTM cell, which mechanism solves the vanishing gradient problem of vanilla RNNs across long sequences?', opts: ['MaxPooling', 'The additive Cell State conveyor belt C_t = f_t ⊙ C_{t-1} + i_t ⊙ C̃_t controlled by the Forget Gate f_t', 'Using Sigmoid at the output', 'Dropping hidden states'], ans: 1, exp: 'Because C_t updates via elementwise addition (+) rather than repeated matrix multiplication by W_hh, gradients flow along C_t when f_t ≈ 1.' },

      // CAT5: Python ML Libraries Encyclopedia & Bro Code Stack (8 Qs)
      { id: 'q41', cat: 'CAT5', q: 'In PyTorch, why must you NEVER place `nn.Softmax()` right before `nn.CrossEntropyLoss()`?', opts: ['PyTorch does not have nn.Softmax', '<code>nn.CrossEntropyLoss</code> internally applies fused <code>LogSoftmax</code> + <code>NLLLoss</code> on raw unnormalized logits for numerical stability; adding Softmax beforehand double-normalizes and ruins gradients!', 'It causes a CUDA out-of-memory error', 'It only works for binary classification'], ans: 1, exp: 'Always return raw logits from your `nn.Module.forward()` and pass them directly to `nn.CrossEntropyLoss()` (or `nn.BCEWithLogitsLoss()`).' },
      { id: 'q42', cat: 'CAT5', q: 'When reading an image with OpenCV `img = cv2.imread("photo.jpg")`, what is the channel order and shape of the returned NumPy array?', opts: ['RGB with shape (3, H, W)', 'BGR with shape (Height, Width, 3) and dtype uint8', 'Grayscale float64', 'RGBA with shape (W, H, 4)'], ans: 1, exp: 'OpenCV defaults to BGR channel order in `(H, W, C)` layout! Always call `cv2.cvtColor(img, cv2.COLOR_BGR2RGB)` before displaying in Matplotlib or feeding to Torchvision.' },
      { id: 'q43', cat: 'CAT5', q: 'In Pandas, how do you impute missing values in `df["price"]` using each row\'s neighborhood median `df.groupby("neighborhood")["price"]` while keeping the original DataFrame length <code>m</code>?', opts: ['df.groupby("neighborhood")["price"].agg("median")', 'df["price"].fillna(df.groupby("neighborhood")["price"].transform("median"))', 'df.dropna()', 'pd.merge()'], ans: 1, exp: '`.groupby(...).transform("median")` broadcasts each group\'s scalar median back to the exact index length <code>m</code> of the original DataFrame.' },
      { id: 'q44', cat: 'CAT5', q: 'What fundamental property do SHAP values φ_j(x) guarantee for any individual prediction f(x)?', opts: ['∑ φ_j(x) = 1.0', 'Local Additivity (Efficiency): E[f(X)] + ∑_{j=1}^n φ_j(x) = f(x) (the baseline plus all feature SHAP values sums to the exact model prediction!)', 'All φ_j(x) are positive', 'They equal Pearson correlation'], ans: 1, exp: 'SHAP decomposes the exact gap between the dataset baseline E[f(X)] and individual prediction f(x) fairly across all n features.' },
      { id: 'q45', cat: 'CAT5', q: 'How does LoRA (Low-Rank Adaptation in Hugging Face <code>peft</code>) fine-tune a 70-billion-parameter LLM on a single GPU?', opts: ['It deletes 90% of the transformer layers', 'It freezes pretrained weights W_0 ∈ ℝ^(d×k) (often quantized to 4-bit NF4 in QLoRA) and trains only tiny low-rank matrices B ∈ ℝ^(d×r) and A ∈ ℝ^(r×k) where r ≪ d (e.g. r=16)', 'It converts the LLM into a Random Forest', 'It trains only the embedding layer'], ans: 1, exp: 'With d=4096 and r=16, B·A has only 2 × 4096 × 16 = 131,072 parameters instead of 4096² = 16.7 million (>99% parameter reduction!).' },
      { id: 'q46', cat: 'CAT5', q: 'In the Bro Code Python Libraries stack, which pair of libraries is used to fetch web pages over HTTP and parse the HTML DOM tree into structured training records?', opts: ['PyGame & OpenCV', 'Requests & BeautifulSoup4 (bs4)', 'Dash & Plotly', 'Keras & SciPy'], ans: 1, exp: '`requests.Session().get(url)` handles HTTP transport, while `BeautifulSoup(html, "html.parser").select(...)` extracts DOM elements via CSS selectors.' },
      { id: 'q47', cat: 'CAT5', q: 'In the Bro Code Python Libraries stack, how do <code>Plotly</code> and <code>Dash</code> work together for Machine Learning analytics?', opts: ['Plotly trains neural networks and Dash scrapes websites', 'Plotly creates interactive WebGL/D3.js charts, and Dash wraps Plotly + Flask + React.js so Python `@callback` functions power full interactive web dashboards', 'They replace NumPy', 'They are C++ compilers'], ans: 1, exp: 'Dash binds UI inputs (<code>dcc.Slider</code>, <code>dcc.Dropdown</code>) to Python model inference functions that return interactive <code>plotly</code> figures.' },
      { id: 'q48', cat: 'CAT5', q: 'When serving a trained Scikit-Learn or PyTorch model via a web API (<code>FastAPI</code>, <code>Flask</code>, or <code>Django</code>), where should `joblib.load("model.joblib")` be called?', opts: ['Inside the `/predict` route function on every single HTTP request', 'ONCE at application startup (global/lifespan scope) in memory, while validating incoming JSON requests with Pydantic before calling `model.predict()`', 'Inside the HTML template', 'On the client browser'], ans: 1, exp: 'Loading a 500MB model file from disk on every HTTP request adds ratusan milliseconds of disk I/O latency and crashes under concurrent load!' }
    ];

    function renderQuizList() {
      const container = document.getElementById('quiz-questions-container');
      if (!container) return;
      const catFilter = document.getElementById('quiz-category-select')?.value || 'ALL';
      const filtered = QUIZ_BANK.filter(q => catFilter === 'ALL' || q.cat === catFilter);

      container.innerHTML = filtered.map((q, idx) => {
        const chosen = appState.quizAnswers[q.id];
        const isAnswered = chosen !== undefined;
        const isCorrect = chosen === q.ans;

        const optsHtml = q.opts.map((optText, oIdx) => {
          let btnStyle = 'bg-[var(--card)] border-[var(--border)] hover:border-[var(--primary)]';
          if (isAnswered) {
            if (oIdx === q.ans) {
              btnStyle = 'bg-emerald-500/20 border-emerald-500 text-emerald-300 font-bold';
            } else if (oIdx === chosen && chosen !== q.ans) {
              btnStyle = 'bg-rose-500/20 border-rose-500 text-rose-300';
            } else {
              btnStyle = 'bg-[var(--card)] border-[var(--border)] opacity-60';
            }
          }
          return `
            <button onclick="answerQuizQuestion('${q.id}', ${oIdx})" class="w-full text-left p-2.5 rounded-lg border text-xs sm:text-sm transition-all ${btnStyle}">
              <span class="font-mono font-bold mr-1.5">${String.fromCharCode(65 + oIdx)}.</span> ${optText}
            </button>
          `;
        }).join('');

        return `
          <div class="p-4 rounded-xl bg-[var(--content)] border border-[var(--border)] flex flex-col justify-between space-y-3">
            <div class="space-y-2.5">
              <div class="flex items-center justify-between text-xs">
                <span class="font-bold uppercase tracking-wider text-[var(--primary)]">Question ${idx + 1} (${q.cat})</span>
                ${isAnswered ? `<span class="font-bold ${isCorrect ? 'text-emerald-400' : 'text-rose-400'}">${isCorrect ? '✅ Correct (+25 XP)' : '❌ Review Proof Below'}</span>` : '<span class="text-[var(--muted-foreground)]">Unanswered</span>'}
              </div>
              <h4 class="font-bold text-sm leading-snug">${q.q}</h4>
              <div class="space-y-1.5 pt-1">${optsHtml}</div>
            </div>
            ${isAnswered ? `
              <div class="p-3 rounded-lg bg-[var(--card)] border border-[var(--border)] text-xs leading-relaxed">
                <strong class="text-[var(--primary)]">Mathematical Explanation:</strong> ${q.exp}
              </div>
            ` : ''}
          </div>
        `;
      }).join('');
    }

    function answerQuizQuestion(qId, optIdx) {
      const q = QUIZ_BANK.find(item => item.id === qId);
      if (!q) return;
      const prev = appState.quizAnswers[qId];
      appState.quizAnswers[qId] = optIdx;
      if (prev === undefined && optIdx === q.ans) {
        addXP(25);
      } else {
        updateHeaderStats();
      }
      renderQuizList();
    }

    function resetAllQuizzes() {
      appState.quizAnswers = {};
      updateHeaderStats();
      renderQuizList();
    }

    // =========================================================================
    // 7. REFERENCE: DEBUGGING DOCTOR, ALGORITHM MATRIX & 50-FORMULA VAULT
    // =========================================================================
    const DEBUGGER_PLAYBOOK = [
      {
        symptom: '🚨 Symptom 1: High Training Error AND High Validation Error (Underfitting / High Bias)',
        cause: 'Model hypothesis class f_θ is too simple to capture the underlying signal, regularization penalty λ is way too high, or features are unscaled for distance/gradient algorithms.',
        fixes: [
          '1. Increase model capacity: increase Polynomial degree, increase Tree <code>max_depth</code> / <code>num_leaves</code>, switch from Linear SVM to RBF Kernel or Gradient Boosting (<code>XGBoost</code>/<code>LightGBM</code>).',
          '2. Decrease regularization penalty: lower <code>alpha</code> in Ridge/Lasso, increase <code>C</code> in SVM/LogisticRegression, or reduce <code>reg_lambda</code>/<code>min_child_samples</code> in GBDTs.',
          '3. Engineer domain interaction features (ratios, polynomial crosses, group aggregations, lag features).',
          '4. Verify feature scaling (<code>StandardScaler</code>) if using KNN, SVM, PCA, Logistic/Ridge/Lasso, or Neural Networks.'
        ]
      },
      {
        symptom: '🔥 Symptom 2: Near-Zero Training Error (99.9%) BUT Huge Validation Error (Overfitting / High Variance)',
        cause: 'Model has too many degrees of freedom relative to sample count m and is memorizing training noise ε.',
        fixes: [
          '1. Add or strengthen Regularization: increase L2 (<code>alpha</code> / <code>weight_decay</code>), L1 (<code>Lasso</code>), Dropout (`p=0.2–0.5`), or cost-complexity pruning (<code>ccp_alpha</code>).',
          '2. Constrain Tree complexity: reduce <code>max_depth</code> (e.g. 4–8), increase <code>min_samples_leaf</code> (e.g. 20–50), and enable `subsample=0.8`, `colsample_bytree=0.8`.',
          '3. Enable Early Stopping (`early_stopping_rounds=50`) monitored on a validation split.',
          '4. Apply Data Augmentation (for CV/NLP) or Feature Selection (<code>SelectFromModel</code>, <code>RFECV</code>) to drop noisy columns.'
        ]
      },
      {
        symptom: '🕵️ Symptom 3: 99.8% Cross-Validation Score, But Terrible Real-World Production Performance',
        cause: 'Data Leakage! Target information or future data leaked into the training features or preprocessing steps.',
        fixes: [
          '1. Wrap ALL imputers, scalers, encoders, and feature selectors inside a <code>sklearn.pipeline.Pipeline</code> + <code>ColumnTransformer</code> so `.fit()` never sees validation folds.',
          '2. Audit features for Anachronistic / Target Leakage (e.g. <code>cancellation_reason</code> or <code>days_late</code> present at loan origination).',
          '3. Replace random <code>KFold</code> with <code>TimeSeriesSplit</code> for temporal forecasting and `GroupKFold(groups=user_id)` when multiple rows belong to the same entity.'
        ]
      },
      {
        symptom: '💥 Symptom 4: Training Loss Explodes to NaN / Inf or Oscillates Wildly',
        cause: 'Learning rate α is too large (overshooting the valley walls), unscaled features have wildly different magnitudes (10^6 vs 10^-3), or log(0) / exp(1000) overflowed.',
        fixes: [
          '1. Lower learning rate α by 10× (e.g. from <code>1e-1</code> to <code>1e-3</code>) and use <code>AdamW</code> with a linear warmup + cosine annealing schedule.',
          '2. Apply <code>StandardScaler</code> / <code>RobustScaler</code> to inputs and <code>LayerNorm</code> / <code>BatchNorm</code> inside deep networks.',
          '3. Apply Gradient Clipping (`torch.nn.utils.clip_grad_norm_(model.parameters(), max_norm=1.0)`).',
          '4. Check for <code>NaN</code>/<code>Inf</code> in raw input data (`np.isnan(X).sum()`) and use fused loss functions (<code>nn.CrossEntropyLoss</code>, <code>nn.BCEWithLogitsLoss</code>).'
        ]
      },
      {
        symptom: '⚖️ Symptom 5: Model Predicts Majority Class 0 for Every Single Row (99% Accuracy, 0% Recall)',
        cause: 'Severe Class Imbalance (e.g. 1% positive rate) combined with the default 0.50 probability threshold and uncalibrated loss weights.',
        fixes: [
          '1. Stop looking at Accuracy! Switch evaluation metric to <code>average_precision</code> (PR-AUC), <code>f1_score</code>, or <code>matthews_corrcoef</code> (Balanced Overall Score).',
          '2. Set `class_weight="balanced"` (in Sklearn) or `scale_pos_weight = count(neg) / count(pos)` (in XGBoost/LightGBM).',
          '3. Tune the decision threshold <code>tau</code> on out-of-fold validation probabilities using <code>TunedThresholdClassifierCV</code> (e.g. lowering threshold from 0.50 to 0.12).',
          '4. Calibrate predicted probabilities with `CalibratedClassifierCV(method="isotonic")`.'
        ]
      }
    ];

    function renderDebuggerPlaybook() {
      const listEl = document.getElementById('debugger-symptoms-list');
      const panelEl = document.getElementById('debugger-diagnosis-panel');
      if (!listEl || !panelEl) return;

      listEl.innerHTML = DEBUGGER_PLAYBOOK.map((item, idx) => {
        const active = idx === appState.activeDebuggerIdx;
        return `
          <button onclick="selectDebuggerSymptom(${idx})" class="w-full text-left p-3 rounded-xl border text-xs sm:text-sm font-bold transition-all ${active ? 'bg-[var(--primary)] text-[var(--primary-foreground)] border-[var(--primary)] shadow-sm' : 'bg-[var(--content)] text-[var(--foreground)] border-[var(--border)] hover:border-[var(--primary)]'}">
            ${item.symptom}
          </button>
        `;
      }).join('');

      const cur = DEBUGGER_PLAYBOOK[appState.activeDebuggerIdx];
      panelEl.innerHTML = `
        <div class="space-y-3">
          <div class="text-xs font-bold uppercase tracking-wider text-rose-400">🔍 Root Mathematical &amp; Engineering Cause</div>
          <p class="text-sm font-semibold leading-relaxed">${cur.cause}</p>
          <div class="text-xs font-bold uppercase tracking-wider text-emerald-400 pt-2">🛠️ Ordered Actionable Fixes</div>
          <ul class="space-y-2 text-xs sm:text-sm">
            ${cur.fixes.map(f => `<li class="p-2.5 rounded-lg bg-[var(--card)] border border-[var(--border)]">${f}</li>`).join('')}
          </ul>
        </div>
      `;
    }

    function selectDebuggerSymptom(idx) {
      appState.activeDebuggerIdx = idx;
      renderDebuggerPlaybook();
    }

    const ALGORITHM_MATRIX = [
      { name: 'Best-Fit Line / Ridge / Lasso / ElasticNet', task: 'Regression', scale: 'YES', comp: 'O(mn²) / O(n)', pros: 'Fast, exact convex optimum, interpretable weights, Lasso selects features.', cons: 'Assumes linear additive relationship (unless Polynomial/Spline expanded).' },
      { name: 'Logistic Regression', task: 'Classification', scale: 'YES', comp: 'O(kmn) / O(n)', pros: 'Well-calibrated probabilities P(y=1|x), fast, log-odds interpretability.', cons: 'Linear hyperplane boundary; cannot solve XOR without nonlinear features.' },
      { name: 'KNN (K-Nearest Neighbors)', task: 'Both', scale: 'YES', comp: 'O(1) / O(mn)', pros: 'Zero training time, naturally adapts to arbitrary local nonlinear geometry.', cons: 'Slow O(mn) prediction, large memory, breaks in high dimensions (d > 30).' },
      { name: 'Naive Bayes (Gaussian / Multinomial)', task: 'Classification', scale: 'NO', comp: 'O(mn) / O(Kn)', pros: 'Single-pass O(mn) training, thrives on 50,000+ sparse NLP word columns.', cons: 'Conditional independence assumption yields overconfident probabilities near 0/1.' },
      { name: 'SVM (Linear & RBF Kernel)', task: 'Both', scale: 'YES', comp: 'O(m²n) / O(n_sv·n)', pros: 'Maximum geometric margin 2/‖w‖₂; Kernel Trick creates smooth nonlinear boundaries.', cons: 'RBF kernel scales poorly past m > 50,000 rows; requires Platt calibration.' },
      { name: 'Decision Tree (CART)', task: 'Both', scale: 'NO', comp: 'O(mn log m) / O(D)', pros: 'White-box if-else flowchart, handles NaNs & mixed types with zero scaling.', cons: 'High variance (unstable); axis-aligned step functions cannot extrapolate trends.' },
      { name: 'Random Forest', task: 'Both', scale: 'NO', comp: 'O(B·m√n log m) / O(BD)', pros: 'Out-of-the-box accuracy, parallelizable (`n_jobs=-1`), Held-Out Rows validation score.', cons: 'Larger RAM footprint and slower inference than a single tree.' },
      { name: 'Gradient Boosting (XGBoost / LightGBM / CatBoost)', task: 'Both + Ranking', scale: 'NO', comp: 'O(B·m·bins) / O(BD)', pros: 'SOTA accuracy on tabular data, native missing value routing & monotonic constraints.', cons: 'Sequential trees can overfit noisy targets if <code>learning_rate</code> / <code>num_leaves</code> untuned.' },
      { name: 'K-Means++ / DBSCAN / GMM', task: 'Clustering', scale: 'YES', comp: 'O(tKm n) / O(Kn)', pros: 'K-Means is fast; DBSCAN finds arbitrary shapes & outliers; GMM gives soft probabilities.', cons: 'Distance metrics require feature scaling; K-Means assumes spherical blobs.' },
      { name: 'PCA / TruncatedSVD / UMAP', task: 'Dim Reduction', scale: 'YES', comp: 'O(min(m³ ,n³))', pros: 'Decorrelates collinear columns, compresses noise, visualizes high-D clusters in 2D/3D.', cons: 'Linear combinations lose individual column interpretability.' },
      { name: 'Deep Learning (MLP / CNN / Transformer)', task: 'Vision, NLP, Audio, Multimodal', scale: 'YES', comp: 'O(Epochs·m·Params)', pros: 'Learns hierarchical representations automatically; supports transfer learning & LoRA.', cons: 'Data/GPU hungry; often outperformed by XGBoost/LightGBM on small tabular tables.' }
    ];

    function renderAlgorithmMatrix() {
      const tbody = document.getElementById('algorithm-matrix-tbody');
      if (!tbody) return;
      const filter = document.getElementById('matrix-scaling-filter')?.value || 'ALL';
      const rows = ALGORITHM_MATRIX.filter(r => filter === 'ALL' || r.scale === filter);
      tbody.innerHTML = rows.map(r => `
        <tr class="hover:bg-[var(--content)] transition-colors">
          <td class="p-3 font-bold text-[var(--primary)]">${r.name}</td>
          <td class="p-3 font-semibold">${r.task}</td>
          <td class="p-3"><span class="px-2 py-0.5 rounded text-xs font-bold ${r.scale === 'YES' ? 'bg-amber-500/20 text-amber-300' : 'bg-emerald-500/20 text-emerald-300'}">${r.scale === 'YES' ? 'YES (Mandatory)' : 'NO (Scale-Invariant)'}</span></td>
          <td class="p-3 font-mono text-xs">${r.comp}</td>
          <td class="p-3 text-xs">${r.pros}</td>
          <td class="p-3 text-xs text-[var(--muted-foreground)]">${r.cons}</td>
        </tr>
      `).join('');
    }

    const FORMULA_50_VAULT = [
      { n: 1, name: 'Linear Hypothesis', eq: 'ŷ = wᵀx + b = ∑ wⱼxⱼ + b', desc: 'Weighted sum of features plus intercept bias.' },
      { n: 2, name: 'Average Squared Error', eq: 'Average Squared Error = (1/m) ∑ (ŷ⁽ⁱ⁾ − y⁽ⁱ⁾)²', desc: 'Average squared residual; penalizes large outliers quadratically.' },
      { n: 3, name: 'Typical Error Size', eq: 'Typical Error Size = √Average Squared Error', desc: 'Error measured in the exact same physical units as target y.' },
      { n: 4, name: 'Average Error Size', eq: 'Average Error Size = (1/m) ∑ |ŷ⁽ⁱ⁾ − y⁽ⁱ⁾|', desc: 'Average absolute residual; robust to outliers (predicts conditional median).' },
      { n: 5, name: 'Huber Loss', eq: '½e² if |e| ≤ δ else δ(|e| − ½δ)', desc: 'Quadratic near 0 (smooth gradient) and linear beyond threshold δ.' },
      { n: 6, name: 'R² (Coefficient of Determination)', eq: 'R² = 1 − [ ∑(y⁽ⁱ⁾ − ŷ⁽ⁱ⁾)² / ∑(y⁽ⁱ⁾ − ȳ)² ]', desc: 'Proportion of target variance explained by the model (1.0 = perfect).' },
      { n: 7, name: 'Clue-Adjusted Score Explained %', eq: 'Clue-Adjusted Score Explained % = 1 − [(1 − R²)(m − 1) / (m − n − 1)]', desc: 'Penalizes R² when adding useless features n that do not improve fit.' },
      { n: 8, name: 'Direct Best-Fit Formula (Closed-Form Best-Fit Line)', eq: 'ŵ = (XᵀX)⁻¹ Xᵀy', desc: 'Exact analytical minimum of Average Squared Error in one step without iterative loops.' },
      { n: 9, name: 'Average Squared Error Gradient Vector', eq: '∇_w J = (2/m) Xᵀ(Xw + b − y)', desc: 'Direction of steepest ascent; subtract α∇_w J to step downhill.' },
      { n: 10, name: 'Downhill Error Stepping Update', eq: 'θ_{t+1} = θ_t − α ∇_θ J(θ_t)', desc: 'Universal iterative parameter update rule with learning rate α.' },
      { n: 11, name: 'Momentum Update', eq: 'v_t = β v_{t-1} + (1 − β)g_t ; θ_{t+1} = θ_t − α v_t', desc: 'Exponential moving average of gradients dampens ravine oscillations.' },
      { n: 12, name: 'Adam Optimizer Update', eq: 'θ_{t+1} = θ_t − α · m̂_t / (√v̂_t + ε)', desc: 'Combines 1st moment m̂_t and 2nd moment v̂_t with startup bias correction.' },
      { n: 13, name: 'Bias-Variance Decomposition', eq: 'E[(y − f̂(x))²] = Bias² + Variance + σ_ε²', desc: 'Total expected test error = underfitting² + overfitting + irreducible noise.' },
      { n: 14, name: 'Ridge Regression (L₂ Objective)', eq: 'J(w) = Average Squared Error + λ ∑ wⱼ²', desc: 'Shrinks correlated weights smoothly toward zero (Gaussian prior MAP).' },
      { n: 15, name: 'Ridge Closed-Form Solution', eq: 'ŵ_Ridge = (XᵀX + λI)⁻¹ Xᵀy', desc: 'Adding λI shifts eigenvalues to λ_k + λ > 0, guaranteeing invertibility!' },
      { n: 16, name: 'Lasso Regression (L₁ Objective)', eq: 'J(w) = Average Squared Error + λ ∑ |wⱼ|', desc: 'Induces sparsity via diamond corners, snapping useless weights to exact 0.0.' },
      { n: 17, name: 'ElasticNet Objective', eq: 'J(w) = ½MSE + α·r‖w‖₁ + ½α(1 − r)‖w‖₂²', desc: 'Combines L₁ feature selection with L₂ grouped correlated stability.' },
      { n: 18, name: 'Sigmoid (Logistic) Function', eq: 'σ(z) = 1 / (1 + e⁻ᶻ)', desc: 'Squashes any real logit z ∈ (-∞, +∞) into a valid probability (0, 1).' },
      { n: 19, name: 'Sigmoid Derivative Identity', eq: 'σ′(z) = σ(z)(1 − σ(z))', desc: 'Self-referential derivative peaking at 0.25 when z = 0.' },
      { n: 20, name: 'Log-Odds (Logit Inverse)', eq: 'ln(p / (1 − p)) = wᵀx + b', desc: 'Logarithm of the odds ratio is linear in features x and weights w.' },
      { n: 21, name: 'Binary Cross-Entropy (Log-Loss)', eq: 'J = −(1/m) ∑ [y ln(p̂) + (1 − y) ln(1 − p̂)]', desc: 'Negative log-likelihood of a Bernoulli target; punishes confident errors.' },
      { n: 22, name: 'Softmax Function', eq: 'P(y=k | x) = e^{z_k} / ∑_{c=1}^K e^{z_c}', desc: 'Generalizes Sigmoid to K ≥ 3 mutually exclusive classes summing to 1.0.' },
      { n: 23, name: 'Euclidean (L₂) Distance', eq: 'd₂(x, z) = √(∑ (xⱼ − zⱼ)²)', desc: 'Straight-line geometric distance; requires feature standardization!' },
      { n: 24, name: 'Manhattan (L₁) Distance', eq: 'd₁(x, z) = ∑ |xⱼ − zⱼ|', desc: 'City-block grid distance along coordinate axes.' },
      { n: 25, name: 'Cosine Similarity', eq: 'cos(θ) = (xᵀz) / (‖x‖₂ ‖z‖₂)', desc: 'Measures angle alignment in [-1, +1] invariant to vector length.' },
      { n: 26, name: 'Bayes Theorem', eq: 'P(y | x) = P(x | y) P(y) / P(x)', desc: 'Posterior = (Likelihood × Prior) / Marginal Evidence.' },
      { n: 27, name: 'Naive Bayes Classifier Rule', eq: 'ŷ = arg max_c [ ln P(y=c) + ∑ ln P(xⱼ | y=c) ]', desc: 'Sums log-likelihoods under conditional independence to prevent underflow.' },
      { n: 28, name: 'Laplace-Smoothed Word Likelihood', eq: 'P(xⱼ | y=c) = (N_{jc} + α) / (N_c + α|V|)', desc: 'Adds pseudocount α=1 so unseen test words never produce 0 probability.' },
      { n: 29, name: 'SVM Margin Street Width', eq: 'Margin Width = 2 / ‖w‖₂', desc: 'Perpendicular distance between gutters wᵀx + b = +1 and −1.' },
      { n: 30, name: 'SVM Primal Hinge Loss Objective', eq: 'min ½‖w‖₂² + C ∑ max(0, 1 − y⁽ⁱ⁾(wᵀx⁽ⁱ⁾ + b))', desc: 'Balances wide street (½‖w‖²) against margin violations (Hinge loss).' },
      { n: 31, name: 'RBF (Gaussian) Kernel', eq: 'K(x, z) = exp(−γ ‖x − z‖₂²)', desc: 'Implicitly computes dot products in an infinite-dimensional Hilbert space.' },
      { n: 32, name: 'Mix-Up Score (CART)', eq: 'Gini(t) = 1 − ∑_{k=1}^K p_k²', desc: 'Probability a randomly labeled item in node t is misclassified (0 = pure).' },
      { n: 33, name: 'Character Randomness', eq: 'H(t) = −∑_{k=1}^K p_k log₂(p_k)', desc: 'Expected information content / disorder measured in bits.' },
      { n: 34, name: 'Information Gain (Tree Split)', eq: 'IG = I(parent) − [(m_L/m)I(L) + (m_R/m)I(R)]', desc: 'Impurity drop achieved by partitioning parent node into Left and Right.' },
      { n: 35, name: 'Tree Size Trimming Objective', eq: 'R_α(T) = R(T) + ccp_alpha · |T|', desc: 'Penalizes tree training error R(T) by number of leaf nodes |T|.' },
      { n: 36, name: 'Random Forest Variance Reduction', eq: 'Var(f̄) = ρ σ² + ((1 − ρ) / B) σ²', desc: 'B trees kill the 2nd term; <code>max_features</code> decorrelates trees to shrink ρ!' },
      { n: 37, name: 'XGBoost Optimal Leaf Weight', eq: 'wⱼ* = −Gⱼ / (Hⱼ + λ)', desc: '2nd-order Newton-Raphson step using summed gradients Gⱼ and Hessians Hⱼ.' },
      { n: 38, name: 'XGBoost Split Structural Gain', eq: 'Gain = ½[ G_L²/(Left Brake Sum+λ) + G_R²/(Right Brake Sum+λ) − (Left Mistake Sum+Right Mistake Sum)²/(Left Brake Sum+Right Brake Sum+λ) ] − γ', desc: 'Exact loss reduction from splitting a leaf minus complexity tax γ.' },
      { n: 39, name: 'Precision, Recall & Precision-Recall Balance', eq: 'P = TP/(TP+FP), R = TP/(TP+FN), Precision-Recall Balance = 2PR/(P+R)', desc: 'Harmonic mean Precision-Recall Balance punishes extreme imbalance between Precision and Recall.' },
      { n: 40, name: 'Matthews Correlation Coefficient', eq: 'Balanced Overall Score = (TP·TN − FP·FN) / √((TP+FP)(TP+FN)(TN+FP)(TN+FN))', desc: 'Balanced correlation in [-1, +1] across all 4 confusion matrix cells.' },
      { n: 41, name: 'K-Means Inertia', eq: 'J = ∑_{i=1}^m ‖x⁽ⁱ⁾ − μ_{c(i)}‖₂²', desc: 'Within-Cluster Sum of Squares minimized by alternating E/M steps.' },
      { n: 42, name: 'Silhouette Coefficient', eq: 's(i) = (b(i) − a(i)) / max(a(i), b(i))', desc: 'Compares intra-cluster cohesion a(i) against nearest cluster separation b(i).' },
      { n: 43, name: 'Sample Covariance Matrix & PCA', eq: 'Σ = (1/(m−1)) X_cᵀ X_c ; Σ v_k = λ_k v_k', desc: 'Eigenvectors v_k of Σ form orthogonal Principal Component directions.' },
      { n: 44, name: 'Z-Score Standardization', eq: 'x_std = (x − μ_train) / σ_train', desc: 'Centers feature to mean 0 and unit variance 1 using training stats.' },
      { n: 45, name: 'ReLU & GELU Activations', eq: 'ReLU(z) = max(0, z) ; GELU(z) = z Φ(z)', desc: 'Non-saturating positive slope (=1) prevents vanishing gradients in deep nets.' },
      { n: 46, name: 'Backpropagation Hidden Error', eq: 'dZ^{[l]} = (dZ^{[l+1]} W^{[l+1]⊤}) ⊙ g′(Z^{[l]})', desc: 'Pulls downstream error backward through transpose weights and activation slope.' },
      { n: 47, name: '2D Convolution Output Size', eq: 'W_out = ⌊(W_in − K + 2P) / S⌋ + 1', desc: 'Spatial output width given input W_in, kernel K, padding P, and stride S.' },
      { n: 48, name: 'Scaled Dot-Product Self-Attention', eq: 'Attention(Q,K,V) = softmax((Q Kᵀ) / √Head Size) V', desc: 'Routes context across tokens in O(1) path length; √Head Size prevents saturation.' },
      { n: 49, name: 'Bellman Optimality & Q-Learning', eq: 'Q(S,A) ← Q(S,A) + α [ R + γ max_{a′} Q(S′,a′) − Q(S,A) ]', desc: 'Bootstraps optimal future value via Temporal Difference (TD) error.' },
      { n: 50, name: 'SHAP Additivity Guarantee', eq: 'f(x) = E[f(X)] + ∑_{j=1}^n φⱼ(x)', desc: 'Game-theoretic Shapley values sum from dataset baseline to exact prediction.' }
    ];

    function render50FormulaVault() {
      const tbody = document.getElementById('formula50-tbody');
      if (!tbody) return;
      const q = (document.getElementById('formula50-search')?.value || '').toLowerCase().trim();
      const filtered = FORMULA_50_VAULT.filter(item =>
        !q || item.name.toLowerCase().includes(q) || item.eq.toLowerCase().includes(q) || item.desc.toLowerCase().includes(q)
      );
      tbody.innerHTML = filtered.map(item => `
        <tr class="hover:bg-[var(--content)] transition-colors">
          <td class="p-2.5 font-mono font-bold text-[var(--muted-foreground)]">${item.n}</td>
          <td class="p-2.5 font-bold text-[var(--primary)]">${item.name}</td>
          <td class="p-2.5 font-mono text-xs font-semibold">${item.eq}</td>
          <td class="p-2.5 text-xs sm:text-sm">${item.desc}</td>
        </tr>
      `).join('');
    }

