    function focusBroCodeLib(libName) {
      const mapping = {
        'matplotlib': { id: 'matplotlib', query: '' },
        'numpy': { id: 'numpy', query: '' },
        'pandas': { id: 'pandas', query: '' },
        'sklearn': { id: 'sklearn', query: '' },
        'pytorch': { id: 'pytorch', query: '' },
        'keras': { id: 'keras_tf', query: 'keras' },
        'opencv': { id: 'opencv_spacy', query: 'opencv' },
        'plotly': { id: 'plotly_dash', query: 'plotly' },
        'dash': { id: 'plotly_dash', query: 'dash' },
        'flask': { id: 'mlops_serving', query: 'flask' },
        'django': { id: 'mlops_serving', query: 'django' },
        'requests': { id: 'web_rl_pygame', query: 'requests' },
        'beautifulsoup': { id: 'web_rl_pygame', query: 'beautifulsoup' },
        'pygame': { id: 'web_rl_pygame', query: 'pygame' }
      };
      const target = mapping[libName.toLowerCase()];
      if (!target) return;

      switchMainTab('libraries');
      const sel = document.getElementById('lib-layer-filter');
      if (sel) sel.value = 'ALL';
      const input = document.getElementById('lib-search-input');
      if (input) input.value = target.query;

      selectLibrary(target.id);
      setTimeout(() => {
        const detailEl = document.getElementById('library-detail-container');
        if (detailEl) {
          detailEl.scrollIntoView({ behavior: 'smooth', block: 'start' });
        }
      }, 50);
    }

