    let MATPLOTLIB_DATA = JSON.parse(JSON.stringify(MATPLOTLIB_DEFAULTS_DATA));

    function initMatplotlibStudio() {
      updateMatplotlibStudio(true);
    }

    function resetMatplotlibStudioDefaults(fullReset = false) {
      const typeSel = document.getElementById('plt-type-select');
      const curType = typeSel ? typeSel.value : 'line';
      const targetType = fullReset ? 'line' : curType;

      if (fullReset) {
        if (typeSel) typeSel.value = 'line';
        MATPLOTLIB_DATA = JSON.parse(JSON.stringify(MATPLOTLIB_DEFAULTS_DATA));
        const shapeSel = document.getElementById('plt-marker-shape');
        if (shapeSel) shapeSel.value = 'o';
        const lineSel = document.getElementById('plt-line-style');
        if (lineSel) lineSel.value = 'dashed';
        const mSlider = document.getElementById('plt-marker-slider');
        if (mSlider) mSlider.value = '12';
        const mVal = document.getElementById('plt-marker-val');
        if (mVal) mVal.textContent = '12';
        const lwSlider = document.getElementById('plt-linewidth-slider');
        if (lwSlider) lwSlider.value = '3.0';
        const lwVal = document.getElementById('plt-linewidth-val');
        if (lwVal) lwVal.textContent = '3.0';
        const colSel = document.getElementById('plt-color-select');
        if (colSel) colSel.value = '#ef4444';
        const gChk = document.getElementById('plt-grid-check');
        if (gChk) gChk.checked = true;
        const lChk = document.getElementById('plt-legend-check');
        if (lChk) lChk.checked = true;
      } else {
        // Reset only current active chart dataset
        MATPLOTLIB_DATA[targetType] = JSON.parse(JSON.stringify(MATPLOTLIB_DEFAULTS_DATA[targetType]));
      }

      const d = MATPLOTLIB_DEFAULTS_DATA[targetType];
      const tIn = document.getElementById('plt-title-input');
      if (tIn && d.title) tIn.value = d.title;
      const xIn = document.getElementById('plt-xlabel-input');
      if (xIn && d.xlabel) xIn.value = d.xlabel;
      const yIn = document.getElementById('plt-ylabel-input');
      if (yIn && d.ylabel) yIn.value = d.ylabel;

      updateMatplotlibStudio(true);
    }

