            <input type="text" id="plt-input-pie-vals" value="${d.values.join(', ')}" oninput="updateMatplotlibStudio(false)" class="w-full p-1.5 rounded bg-[var(--card)] border border-[var(--border)] text-xs font-mono text-[var(--foreground)]" />
