  // 7. Add Live Changeable Plain-English Graph Descriptions to Existing Curriculum Canvases & Tab 4 Simulators
  function ensureSimLiveDescBox(canvasId, boxId) {
    const canvas = document.getElementById(canvasId);
    if (!canvas) return null;
    let box = document.getElementById(boxId);
    if (!box) {
      box = document.createElement('div');
      box.id = boxId;
      box.className = 'mt-2.5 p-3 rounded-xl bg-slate-900/90 border border-sky-500/40 text-xs text-slate-200 leading-relaxed shadow-sm';
      canvas.parentNode.insertBefore(box, canvas.nextSibling);
    }
    return box;
  }

