(function() {
  if (typeof CURRICULUM_MODULES !== 'undefined') window.CURRICULUM_MODULES = CURRICULUM_MODULES;
  if (typeof appState !== 'undefined') window.appState = appState;
  if (typeof QUIZ_BANK !== 'undefined') window.QUIZ_BANK = QUIZ_BANK;
  if (typeof CODING_LABS !== 'undefined') window.CODING_LABS = CODING_LABS;
  if (typeof DISSECTED_FORMULAS !== 'undefined') window.DISSECTED_FORMULAS = DISSECTED_FORMULAS;
  if (typeof FORMULA_50_VAULT !== 'undefined') window.FORMULA_50_VAULT = FORMULA_50_VAULT;

  window.renderCurriculumSidebar = function() {
    const q = (document.getElementById('module-search-input')?.value || '').toLowerCase();
    const lvl = document.getElementById('module-level-filter')?.value || 'ALL';
    const listEl = document.getElementById('curriculum-sidebar-list');
    if (!listEl) return;

    if (window.appState && window.appState.sidebarFocusLevelOnly === undefined) {
      const savedFocus = localStorage.getItem('agy_sidebar_focus_level');
      window.appState.sidebarFocusLevelOnly = (savedFocus !== '0');
    }

    const activeMod = CURRICULUM_MODULES.find(m => m.id === appState.activeModuleId) || CURRICULUM_MODULES[0];
    const activeLevel = activeMod ? (activeMod.level || 'LEVEL 0') : 'LEVEL 0';

    const filtered = CURRICULUM_MODULES.filter(m => {
      if (q) {
        return (m.title + ' ' + m.subtitle + ' ' + m.chapter + ' ' + m.intuition + ' ' + (m.keyPoints || []).join(' ')).toLowerCase().includes(q);
      }
      if (window.appState && window.appState.sidebarFocusLevelOnly) {
        return (m.level === activeLevel);
      }
      if (lvl !== 'ALL' && !(m.level || '').startsWith(lvl)) return false;
      return true;
    });

    const mobSel = document.getElementById('mobile-module-select');
    if (mobSel) {
      mobSel.innerHTML = CURRICULUM_MODULES.map(m => `
        <option value="${m.id}" ${m.id === appState.activeModuleId ? 'selected' : ''}>
          ${m.chapter}: ${m.title}
        </option>
      `).join('');
    }

    const isFocus = window.appState && window.appState.sidebarFocusLevelOnly && !q;
    const headerHtml = `
      <div class="p-2.5 mb-2.5 rounded-xl bg-[var(--card)] border border-[var(--border)] space-y-1.5 shadow-sm">
        <div class="flex items-center justify-between text-xs">
          <span class="font-bold text-sky-400">
            ${isFocus ? ('🎯 ' + activeLevel + ' (' + filtered.length + ' Modules)') : ('📚 All ' + CURRICULUM_MODULES.length + ' Modules')}
          </span>
          <button type="button" onclick="window.toggleSidebarLevelFocus()" class="px-2 py-0.5 rounded-lg text-xs font-bold border transition cursor-pointer ${isFocus ? 'bg-sky-500/20 text-sky-300 border-sky-400/40' : 'bg-[var(--content)] text-slate-300 border-[var(--border)]'}">
            ${isFocus ? 'Show All 31' : 'Focus Level Only'}
          </button>
        </div>
        <p class="text-[11px] text-[var(--muted-foreground)]">
          ${isFocus ? 'Showing only this level to eliminate clutter.' : 'Showing all curriculum modules.'}
        </p>
      </div>
    `;

    const itemsHtml = filtered.map(m => {
      const isActive = m.id === appState.activeModuleId;
      const isDone = (appState.completedModules && typeof appState.completedModules.has === 'function')
        ? appState.completedModules.has(m.id)
        : Array.isArray(appState.completedModules) && appState.completedModules.includes(m.id);
      return `
        <button onclick="selectCurriculumModule('${m.id}')" class="w-full text-left p-3 rounded-xl border transition-all ${isActive ? 'bg-[var(--primary)] text-[var(--primary-foreground)] border-[var(--primary)] shadow-sm' : 'bg-[var(--content)] text-[var(--foreground)] border-[var(--border)] hover:border-[var(--primary)]'}">
          <div class="flex items-center justify-between text-xs opacity-85">
            <span class="font-bold font-mono">${m.chapter}</span>
            <span class="font-bold">${isDone ? '✅ Done' : m.level}</span>
          </div>
          <div class="font-bold text-xs sm:text-sm mt-1 leading-snug">${m.title}</div>
        </button>
      `;
    }).join('');

    const stickyFooterHtml = `
      <div class="sticky bottom-0 mt-3 p-2.5 rounded-xl bg-[var(--card)]/95 border-t border-[var(--border)] backdrop-blur flex items-center justify-between gap-2 shadow-lg">
        <a href="index.html" class="px-3 py-1.5 rounded-lg bg-[var(--content)] hover:bg-[var(--secondary)] text-xs font-bold text-[var(--foreground)] border border-[var(--border)]">
          🏠 Home
        </a>
        <button type="button" onclick="window.jumpToRecommendedNextModule()" class="px-3.5 py-1.5 rounded-lg bg-gradient-to-r from-emerald-500 to-sky-500 text-slate-950 text-xs font-extrabold hover:opacity-95 shadow">
          ▶ Next Card →
        </button>
      </div>
    `;

    listEl.innerHTML = headerHtml + '<div class="space-y-1.5">' + itemsHtml + '</div>' + stickyFooterHtml;
  };

  window.toggleSidebarLevelFocus = function() {
    if (typeof appState !== 'undefined') {
      appState.sidebarFocusLevelOnly = !appState.sidebarFocusLevelOnly;
      try {
        localStorage.setItem('agy_sidebar_focus_level', appState.sidebarFocusLevelOnly ? '1' : '0');
      } catch (_) {}
      window.renderCurriculumSidebar();
    }
  };

  window.jumpToRecommendedNextModule = function() {
    if (window.AcademyCore && typeof window.AcademyCore.loadAcademyStorage === 'function') {
      const st = window.AcademyCore.loadAcademyStorage('ml');
      const done = new Set(st.completedModules || []);
      const nextMod = CURRICULUM_MODULES.find(m => !done.has(m.id)) || CURRICULUM_MODULES[0];
      if (nextMod) {
        window.selectCurriculumModule(nextMod.id, true);
      }
    }
  };

  window.renderActiveCurriculumModule = function() {
    const m = CURRICULUM_MODULES.find(x => x.id === appState.activeModuleId) || CURRICULUM_MODULES[0];
    const container = document.getElementById('curriculum-module-content') || document.getElementById('curriculum-main-content');
    if (!container || !m) return;

    const isDone = (appState.completedModules && typeof appState.completedModules.has === 'function')
      ? appState.completedModules.has(m.id)
      : Array.isArray(appState.completedModules) && appState.completedModules.includes(m.id);

    const mastery = (typeof ML_MODULE_MASTERY_DATA !== 'undefined' && ML_MODULE_MASTERY_DATA[m.id]) ? ML_MODULE_MASTERY_DATA[m.id] : null;
    const roleInfo = (window.V7_EXISTING_MODULE_ROLES && window.V7_EXISTING_MODULE_ROLES[m.id]) || null;
    const roleType = (mastery && mastery.roleType) || (roleInfo ? roleInfo[0] : '🤖 MACHINE LEARNING MODULE');
    const usedByModels = (mastery && mastery.usedByModels) || (roleInfo ? roleInfo[1] : '');

    const idx = CURRICULUM_MODULES.findIndex(x => x.id === m.id);
    const prevMod = idx > 0 ? CURRICULUM_MODULES[idx - 1] : null;
    const nextMod = idx < CURRICULUM_MODULES.length - 1 ? CURRICULUM_MODULES[idx + 1] : null;

    const roleBannerHtml = window.AcademyCore
      ? window.AcademyCore.renderRoleBanner({ badge: roleType, text: usedByModels })
      : '';

    // ------------------------------------------------------------------------
    // PART 1: Intuition, Physical Analogy & Socratic Q&A
    // ------------------------------------------------------------------------
    const physicalIntuitionHtml = (mastery && mastery.physicalIntuition) ? `
      <div class="p-4 rounded-xl bg-gradient-to-r from-emerald-950/40 to-sky-950/40 border border-emerald-500/40 space-y-2">
        <div class="text-xs font-bold text-emerald-300 uppercase tracking-wider">🪵 Everyday 15-Year-Old Intuition (Real-World Analogy)</div>
        <p class="text-xs sm:text-sm text-[var(--foreground)] leading-relaxed">${mastery.physicalIntuition}</p>
      </div>
    ` : '';

    const socraticHtml = (mastery && mastery.socraticQA && mastery.socraticQA.length) ? `
      <div class="rounded-2xl p-5 bg-[var(--card)] border border-sky-500/30 space-y-3">
        <div class="flex items-center justify-between flex-wrap gap-2">
          <div class="text-xs font-bold uppercase tracking-wider text-sky-400">🙋 Socratic "Wait... Why / What / How?" Walkthrough</div>
          <span class="text-xs px-2 py-0.5 rounded bg-sky-500/10 text-sky-300 border border-sky-500/20">15-Year-Old Friendly</span>
        </div>
        <div class="grid grid-cols-1 md:grid-cols-3 gap-3">
          ${mastery.socraticQA.map(item => `
            <div class="p-3.5 rounded-xl bg-[var(--content)] border border-[var(--border)] flex flex-col justify-between space-y-2">
              <div class="text-xs font-bold text-amber-300">❓ "${item.q}"</div>
              <div class="text-xs text-[var(--foreground)] leading-relaxed">${item.a}</div>
            </div>
          `).join('')}
        </div>
      </div>
    ` : '';

    const part1Html = `
      <div class="space-y-5">
        ${roleBannerHtml}
        <div class="p-5 rounded-2xl bg-[var(--content)] border-2 border-emerald-500/40 space-y-2 shadow-sm">
          <div class="flex items-center justify-between">
            <span class="text-xs font-bold uppercase tracking-wider text-emerald-400">💡 Step 1 • Plain-English Intuition &amp; Real-World Meaning First</span>
            <span class="text-xs font-mono text-[var(--muted-foreground)]">Intuition Before Equations</span>
          </div>
          <p class="text-xs sm:text-sm text-[var(--foreground)] leading-relaxed">${m.intuition || ''}</p>
        </div>
        ${physicalIntuitionHtml}
        ${socraticHtml}
      </div>
    `;

    // ------------------------------------------------------------------------
    // PART 2: Interactive Visual Studio & Live Parameter Playground
    // ------------------------------------------------------------------------
    const modsWithoutCanvas = ['mod3', 'mod5', 'mod6', 'mod8', 'mod10', 'mod11', 'mod13', 'mod15', 'mod16', 'mod17'];
    const univStudioHtml = modsWithoutCanvas.includes(m.id) ? `
      <div id="ml-mod-universal-studio" class="p-4 rounded-xl bg-[var(--card)] border border-emerald-500/40 space-y-3">
        <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-[var(--border)] pb-2">
          <div>
            <span class="text-xs font-bold uppercase tracking-wider text-emerald-400">📈 Interactive Visual Graph Studio &amp; Live Plain-English Description</span>
            <h4 class="text-sm sm:text-base font-bold text-[var(--foreground)]">Drag the Sliders to Watch the Graph &amp; Live Explanation Update in Real Time</h4>
          </div>
          <span class="text-xs font-mono text-sky-400">Interactive HTML5 Canvas</span>
        </div>
        <div class="grid grid-cols-1 sm:grid-cols-2 gap-3 text-xs">
          <div class="p-2.5 rounded-lg bg-[var(--content)] border border-[var(--border)]">
            <div class="flex justify-between font-bold mb-1"><span>Primary Parameter Knob 1:</span><span id="ml-univ-v1" class="text-sky-400 font-mono">50</span></div>
            <input type="range" id="ml-univ-s1" aria-label="Primary Parameter Knob 1" min="5" max="95" value="50" oninput="updateMlModUniversalSim('${m.id}')" class="w-full accent-sky-500 cursor-pointer" />
          </div>
          <div class="p-2.5 rounded-lg bg-[var(--content)] border border-[var(--border)]">
            <div class="flex justify-between font-bold mb-1"><span>Secondary Parameter Knob 2:</span><span id="ml-univ-v2" class="text-emerald-400 font-mono">50</span></div>
            <input type="range" id="ml-univ-s2" aria-label="Secondary Parameter Knob 2" min="5" max="95" value="50" oninput="updateMlModUniversalSim('${m.id}')" class="w-full accent-emerald-500 cursor-pointer" />
          </div>
        </div>
        <div class="bg-[#0f172a] border border-slate-700 rounded-xl p-2">
          <canvas id="ml-mod-universal-canvas" role="img" aria-label="Interactive ML Parameter Plot" width="560" height="210" class="w-full h-auto rounded-lg"></canvas>
        </div>
        <div id="ml-mod-universal-desc" class="p-3 rounded-lg bg-slate-900/90 border border-sky-500/30 text-xs text-slate-200 leading-relaxed" aria-live="polite"></div>
      </div>
    ` : '';

    const part2Html = `
      <div class="space-y-5">
        <div id="ml-visual-studio-slot-${m.id}" class="space-y-4">
          ${m.extraSectionsHtml || ''}
          ${univStudioHtml}
        </div>
      </div>
    `;

    // ------------------------------------------------------------------------
    // PART 3: Worked Single-Parameter & Multi-Parameter Arithmetic Trace
    // ------------------------------------------------------------------------
    const chainHtml = (mastery && mastery.chain && mastery.chain.length) ? `
      <div id="ml-formula-chain-banner" class="p-4 rounded-xl bg-slate-900/90 border border-indigo-500/40 space-y-3">
        <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-1 border-b border-slate-800 pb-2">
          <span class="text-xs font-bold uppercase tracking-wider text-indigo-400">🔗 How All Formulas in This Topic Connect (Cause-and-Effect Chain)</span>
          <span class="text-xs font-mono text-emerald-400">Every Step Feeds the Next</span>
        </div>
        <div class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-2.5">
          ${mastery.chain.map(c => `
            <div class="p-3 rounded-lg bg-slate-950/90 border border-slate-800 space-y-1">
              <div class="text-xs font-bold text-sky-400">${c.step}</div>
              <div class="font-mono text-xs font-bold text-white bg-slate-900 px-2 py-1 rounded border border-slate-700">${c.eq}</div>
              <div class="text-xs text-slate-300 leading-snug">${c.why}</div>
            </div>
          `).join('')}
        </div>
      </div>
    ` : '';

    const workedHtml = typeof formatEyeFriendlyWorkedExample === 'function'
      ? formatEyeFriendlyWorkedExample(m.workedExample, m.id)
      : `<p class="text-xs sm:text-sm font-mono leading-relaxed">${m.workedExample || ''}</p>`;

    const part3Html = `
      <div class="space-y-5">
        ${chainHtml}
        <div id="curriculum-worked-example-container" class="space-y-4">
          ${workedHtml}
        </div>
      </div>
    `;

    // ------------------------------------------------------------------------
    // PART 4: Mathematical Blueprint, Symbol Decoder Table & Key Mechanics
    // ------------------------------------------------------------------------
    const decoderTableHtml = (mastery && mastery.symbols && mastery.symbols.length) ? `
      <div class="ml-step4-decoder space-y-3 pt-2">
        ${mastery.plainFormula ? `
          <div class="p-3 rounded-lg bg-indigo-950/40 border border-indigo-500/40 text-xs sm:text-sm">
            <div class="text-xs font-bold uppercase tracking-wider text-indigo-300 mb-1">🗣️ Read-Aloud Plain-English Translation (Zero Jargon):</div>
            <div class="font-mono font-bold text-emerald-300 leading-relaxed">${mastery.plainFormula}</div>
          </div>
        ` : ''}
        <div class="overflow-x-auto rounded-lg border border-[var(--border)] bg-[var(--card)]">
          <div class="px-3 py-2 bg-[var(--content)] border-b border-[var(--border)] text-xs font-bold text-indigo-400">
            🔍 Symbol-by-Symbol Formula Decoder (What Every Single Letter &amp; Greek Symbol Means)
          </div>
          <table class="w-full text-left border-collapse text-xs">
            <thead class="bg-slate-900/60 text-[var(--muted-foreground)] uppercase">
              <tr>
                <th class="p-2.5 border-b border-r border-[var(--border)]">Symbol</th>
                <th class="p-2.5 border-b border-r border-[var(--border)]">Name / Role</th>
                <th class="p-2.5 border-b border-[var(--border)]">Plain-English Meaning &amp; How It Affects the Result</th>
              </tr>
            </thead>
            <tbody class="divide-y divide-[var(--border)]">
              ${mastery.symbols.map(s => `
                <tr class="hover:bg-[var(--content)]/50">
                  <td class="p-2.5 font-mono font-bold text-amber-400 border-r border-[var(--border)] whitespace-nowrap">${s.sym}</td>
                  <td class="p-2.5 font-bold text-[var(--foreground)] border-r border-[var(--border)]">${s.name}</td>
                  <td class="p-2.5 text-[var(--muted-foreground)] leading-relaxed">${s.meaning}</td>
                </tr>
              `).join('')}
            </tbody>
          </table>
        </div>
      </div>
    ` : '';

    const part4Html = `
      <div class="space-y-5">
        <div class="p-5 rounded-2xl bg-[var(--content)] border border-sky-500/30 space-y-3">
          <div class="flex items-center justify-between flex-wrap gap-2">
            <span class="text-xs font-bold uppercase tracking-wider text-sky-400">📐 Mathematical Blueprint &amp; Term-by-Term Anatomy</span>
            <a href="machine_learning_formula_rosetta_stone.html" class="text-xs font-bold text-amber-400 hover:text-amber-300 underline">🗿 Open Symbol Rosetta Stone →</a>
          </div>
          <div class="math-block p-4 rounded-xl bg-[var(--card)] border border-[var(--border)] font-mono text-sm sm:text-base text-center overflow-x-auto text-sky-300">
            ${m.formulaHtml || ''}
          </div>
          ${decoderTableHtml}
        </div>
        <div class="p-5 rounded-2xl bg-[var(--content)] border border-[var(--border)] space-y-3">
          <h3 class="text-xs font-bold uppercase tracking-wider text-purple-400">🔬 Conceptual Architecture &amp; Step-by-Step Mechanics</h3>
          <div class="space-y-2.5">
            ${(m.keyPoints || []).map(pt => `
              <div class="p-3.5 rounded-lg bg-[var(--card)] border border-[var(--border)] text-xs sm:text-sm leading-relaxed">
                ${pt}
              </div>
            `).join('')}
          </div>
        </div>
      </div>
    `;

    // ------------------------------------------------------------------------
    // PART 5: Annotated Python Implementation & Mastery Check
    // ------------------------------------------------------------------------
    const safeCode = window.AcademyCore ? window.AcademyCore.escapeHtml(m.codeSnippet || '') : (m.codeSnippet || '');
    const part5Html = `
      <div class="space-y-5">
        <div class="rounded-2xl bg-[var(--content)] border border-[var(--border)] overflow-hidden">
          <div class="p-4 border-b border-[var(--border)] flex flex-wrap items-center justify-between gap-2 bg-[var(--card)]">
            <div>
              <div class="text-xs font-bold uppercase tracking-wider text-emerald-400">💻 Line-by-Line Code Microscope (NumPy &amp; Scikit-Learn)</div>
              <div class="text-xs text-[var(--muted-foreground)]">Production reference implementation with mathematical comments</div>
            </div>
            <div class="flex items-center gap-2">
              <button onclick="copyTextToClipboard(CURRICULUM_MODULES[${idx}].codeSnippet, this)" class="px-2.5 py-1.5 rounded-lg bg-[var(--content)] border border-[var(--border)] text-xs font-semibold hover:opacity-80 cursor-pointer">📋 Copy Code</button>
              <button onclick="switchMainTab('coding')" class="px-3 py-1.5 rounded-lg bg-emerald-500/10 hover:bg-emerald-500/20 text-emerald-300 border border-emerald-500/30 text-xs font-bold cursor-pointer">
                ⚡ Open in Coding Sandbox →
              </button>
            </div>
          </div>
          <pre class="p-4 text-xs sm:text-sm font-mono overflow-x-auto leading-relaxed text-emerald-300">${safeCode}</pre>
        </div>
      </div>
    `;

    // ------------------------------------------------------------------------
    // Assemble Module Shell + Part Pager Host
    // ------------------------------------------------------------------------
    container.innerHTML = `
      <div class="space-y-5">
        <!-- Module Header -->
        <div class="flex flex-wrap items-start justify-between gap-4 pb-4 border-b border-[var(--border)]">
          <div class="space-y-1.5">
            <div class="flex flex-wrap items-center gap-2">
              <span class="px-2.5 py-0.5 rounded-full text-xs font-bold bg-emerald-500/15 text-emerald-400 border border-emerald-500/30">${m.level}</span>
              <span class="text-xs font-mono text-[var(--muted-foreground)]">${m.chapter}</span>
              <span class="text-xs px-2 py-0.5 rounded bg-[var(--content)] border border-[var(--border)] text-sky-400 font-semibold">5 Bite-Sized Parts</span>
            </div>
            <h2 class="text-xl sm:text-2xl font-extrabold tracking-tight text-[var(--foreground)]">${m.title}</h2>
            <p class="text-xs sm:text-sm text-[var(--muted-foreground)]">${m.subtitle}</p>
          </div>
          <div class="flex items-center gap-2">
            <button onclick="toggleCompleteModule('${m.id}')"
              class="px-4 py-2 rounded-xl text-xs font-bold border transition cursor-pointer ${
                isDone
                  ? 'bg-emerald-500 text-slate-950 border-emerald-400 shadow-lg shadow-emerald-500/20'
                  : 'bg-[var(--content)] text-[var(--foreground)] border-[var(--border)] hover:border-emerald-500/50'
              }">
              ${isDone ? '✓ Module Completed (+25 XP)' : '○ Mark Module Complete (+25 XP)'}
            </button>
          </div>
        </div>

        <!-- V8 Part Pager Mount Point -->
        <div id="v8-module-pager-root"></div>

        <!-- Module-to-Module Footer Navigation -->
        <div class="pt-4 border-t border-[var(--border)] flex flex-wrap items-center justify-between gap-3">
          ${prevMod ? `
            <button onclick="selectCurriculumModule('${prevMod.id}')" class="px-4 py-2 rounded-xl bg-[var(--content)] hover:bg-[var(--secondary)] border border-[var(--border)] text-xs font-semibold cursor-pointer">
              ← Previous Module: ${prevMod.chapter}
            </button>
          ` : `<div></div>`}
          ${nextMod ? `
            <button onclick="selectCurriculumModule('${nextMod.id}')" class="px-4 py-2 rounded-xl bg-sky-500/15 hover:bg-sky-500/25 border border-sky-500/40 text-sky-300 text-xs font-bold cursor-pointer">
              Next Module: ${nextMod.chapter} (${nextMod.title.slice(0, 38)}...) →
            </button>
          ` : `<div></div>`}
        </div>
      </div>
    `;

    function runPartStudios() {
      if (typeof window.initActiveCurriculumModuleSims === 'function') {
        window.initActiveCurriculumModuleSims();
      }
      if (typeof window.updateMlModUniversalSim === 'function') {
        window.updateMlModUniversalSim(m.id);
      }
    }

    // Mount the 5-Part Stepper via AcademyCore
    if (window.AcademyCore && typeof window.AcademyCore.mountPartPager === 'function') {
      window.AcademyCore.mountPartPager({
        hostEl: document.getElementById('v8-module-pager-root'),
        moduleId: m.id,
        idPrefix: 'v8-ml',
        parts: [
          {
            badge: 'Part 1 • Intuition & Plain English',
            title: 'Why Does This Exist & What Real-World Problem Does It Solve?',
            subtitle: 'Understand the "Why" and "What" in plain 15-year-old-friendly English before seeing a single equation.',
            html: part1Html
          },
          {
            badge: 'Part 2 • Interactive Studio & Live Lab',
            title: 'How Does the Interactive Visual Move & What Happens When You Change Inputs?',
            subtitle: 'Make a prediction, drag the sliders, and test single-parameter vs multi-parameter inputs on the live graph.',
            html: part2Html,
            onShow: function() {
              setTimeout(runPartStudios, 20);
            }
          },
          {
            badge: 'Part 3 • Worked 1D & Multi-D Numbers',
            title: 'What Do the Exact Numbers Look Like Step by Step Without Skipping Steps?',
            subtitle: 'Follow the exact 1-parameter and multi-parameter tables with real numbers and zero skipped steps.',
            html: part3Html,
            onShow: function() {
              if (m.id === 'mod0' && typeof window.drawMod0Step2House === 'function') {
                setTimeout(window.drawMod0Step2House, 20);
              }
            }
          },
          {
            badge: 'Part 4 • Formula & Mechanics',
            title: 'What Is the Exact Mathematical Blueprint & Formula?',
            subtitle: 'Every Greek symbol and letter translated into plain English, plus under-the-hood mechanics.',
            html: part4Html
          },
          {
            badge: 'Part 5 • Python Code & Mastery Check',
            title: 'How Do We Write It in Python & Test Our Understanding?',
            subtitle: 'See how the math translates into Python/Scikit-Learn code and verify your mastery.',
            html: part5Html
          }
        ]
      });
      if (typeof window.AcademyCore.enhanceRenderedModule === 'function') {
        window.AcademyCore.enhanceRenderedModule(m.id);
      }
    }

    setTimeout(runPartStudios, 30);
  };

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', function() {
      const urlMod = window.AcademyCore ? window.AcademyCore.getQueryParam('mod') : null;
      if (urlMod && CURRICULUM_MODULES.some(x => x.id === urlMod)) {
        appState.activeModuleId = urlMod;
      }
      window._v8BootDone = true;
      window.renderCurriculumSidebar();
      window.renderActiveCurriculumModule();
    });
  } else {
    const urlMod = window.AcademyCore ? window.AcademyCore.getQueryParam('mod') : null;
    if (urlMod && CURRICULUM_MODULES.some(x => x.id === urlMod)) {
      appState.activeModuleId = urlMod;
    }
    window._v8BootDone = true;
    window.renderCurriculumSidebar();
    window.renderActiveCurriculumModule();
  }
})();
